const state={pipelines:[],current:null,config:null,stores:[],aiProvider:null,objectStorage:null,account:null,team:{members:[],roles:{}},registrations:{accounts:[],total:0},operations:null,productCatalog:{summary:{},products:[]},marketResearch:{summary:{},candidates:[],rules:null},researchSearch:'',researchDecisionFilter:'all',researchSort:'score_desc',researchCandidateId:null,selectedCatalogIds:new Set(),selectedPipelineIds:new Set(),selectedResearchIds:new Set(),selectedAssetIds:new Set(),supplierMonitor:{summary:{},products:[]},supplierMonitorJob:null,supplierMonitorTimer:null,batchProcessJob:null,batchProcessTimer:null,batchProcessHistoryMode:false,versionPipelineId:null,assetLibrary:{summary:{},assets:[]},activity:[],notifications:{notifications:[],unread_count:0},dashboard:{counters:{},issues:[]},batchImportJob:null,batchImportTimer:null,dialogStage:null,imageSelection:[],imageReview:null,skuSource:null,pipelineSearch:'',pipelineFilter:'all',taskFilter:'all',catalogSearch:'',catalogStatusFilter:'all',assetSearch:'',assetTypeFilter:'all',assetStatusFilter:'all'};
