const $=selector=>document.querySelector(selector);
async function api(path,options={}){const response=await fetch(path,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});const raw=await response.text();let data;try{data=raw?JSON.parse(raw):{}}catch{const preview=raw.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim().slice(0,160);throw new Error(`HTTP ${response.status} 返回非 JSON${preview?`：${preview}`:''}`)}if(response.status===401){location.replace('/login');throw new Error('登录已过期，请重新登录')}if(!response.ok)throw new Error(data.error||`HTTP ${response.status}`);return data}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className=`toast show${error?' error':''}`;clearTimeout(el.timer);el.timer=setTimeout(()=>el.className='toast',3500)}
function escapeHtml(value){return String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function stageStatus(pipeline,n){return pipeline?.stages?.[String(n)]?.status||'LOCKED'}
function formatDate(value){if(!value)return '—';const date=new Date(value);if(Number.isNaN(date.getTime()))return String(value);return new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(date)}
function hasPermission(permission){return(state.account?.identity?.permissions||[]).includes(permission)}
function canRun(n){if(stageStatus(state.current,n)==='RUNNING')return false;const permission=n===1?'pipeline.create':n===3?'images.manage':n===5?'listing.publish':'stage.run';if(!hasPermission(permission))return false;if(n===1)return true;if(n===2&&!state.stores.length)return false;return stageStatus(state.current,n-1)==='PASS'}
function selectedStoreId(){return state.current?.store_id||state.stores[0]?.store_id||''}
function storeOptions(selected=selectedStoreId(),onlySelected=false){if(!state.stores.length)return '<option value="">请先授权 OZON 店铺</option>';const stores=onlySelected&&selected?state.stores.filter(store=>store.store_id===selected):state.stores;return stores.map(store=>`<option value="${escapeHtml(store.store_id)}" ${store.store_id===selected?'selected':''}>${escapeHtml(store.name)} · ${escapeHtml(store.currency_code)}</option>`).join('')}
function pipelineBucket(p){const values=Object.values(p.stages||{}).map(stage=>stage.status);const done=values.filter(status=>status==='PASS').length;if(done===5)return'completed';if(values.includes('RUNNING'))return'running';if(values.includes('FAIL'))return'failed';return'draft'}
function renderList(){const root=$('#pipelineList');const query=state.pipelineSearch.toLowerCase();const filtered=state.pipelines.filter(p=>(!query||String(p.title_zh||'').toLowerCase().includes(query))&&(state.pipelineFilter==='all'||pipelineBucket(p)===state.pipelineFilter));$('#pipelineCount').textContent=`${filtered.length} / ${state.pipelines.length} 个任务`;if(!filtered.length){root.innerHTML=`<div class="empty">${state.pipelines.length?'没有符合标题条件的商品任务。':'暂无商品任务，输入 1688 商品 ID 开始。'}</div>`;updatePipelineSelection(filtered);return}root.innerHTML=filtered.map(p=>{const done=Object.values(p.stages||{}).filter(s=>s.status==='PASS').length;const bucket=pipelineBucket(p);const bucketName={completed:'已完成',failed:'需要处理',running:'运行中',draft:'处理中'}[bucket];const title=p.title_zh||'正在读取商品标题';return `<div class="pipeline-item ${state.current?.pipeline_id===p.pipeline_id?'active':''}" data-id="${escapeHtml(p.pipeline_id)}"><input type="checkbox" data-pipeline-select="${escapeHtml(p.pipeline_id)}" ${state.selectedPipelineIds.has(String(p.pipeline_id))?'checked':''} aria-label="选择 ${escapeHtml(title)}"><span class="pipeline-dot ${done===5?'done':''}"></span><span class="pipeline-info"><b title="${escapeHtml(title)}">${escapeHtml(title)}</b><small>1688 · ${escapeHtml(p.pipeline_id)} · ${formatDate(p.updated_at)} · ${bucketName}</small></span><span class="pipeline-progress">${done}/5</span><button class="row-delete" type="button" data-delete-pipeline="${escapeHtml(p.pipeline_id)}">删除</button></div>`}).join('');root.querySelectorAll('.pipeline-item').forEach(el=>el.onclick=event=>{if(event.target.closest('input,button'))return;selectPipeline(el.dataset.id)});root.querySelectorAll('[data-pipeline-select]').forEach(control=>control.onchange=()=>{const id=String(control.dataset.pipelineSelect);control.checked?state.selectedPipelineIds.add(id):state.selectedPipelineIds.delete(id);updatePipelineSelection(filtered)});root.querySelectorAll('[data-delete-pipeline]').forEach(button=>button.onclick=()=>deletePipelines([button.dataset.deletePipeline]));updatePipelineSelection(filtered)}
function updatePipelineSelection(rows=state.pipelines){const selected=state.selectedPipelineIds.size;$('#deleteSelectedPipelinesBtn').textContent=`删除（${selected}）`;$('#deleteSelectedPipelinesBtn').disabled=!selected||!hasPermission('pipeline.create');const all=rows.length>0&&rows.every(item=>state.selectedPipelineIds.has(String(item.pipeline_id)));$('#pipelineSelectAll').checked=all;$('#pipelineSelectAll').indeterminate=!all&&rows.some(item=>state.selectedPipelineIds.has(String(item.pipeline_id)))}
async function deletePipelines(ids){const unique=[...new Set(ids.map(String))];if(!unique.length)return;if(!confirm(`确认删除选中的 ${unique.length} 个 ERP 商品任务？\n\n这会删除本地采集资料、阶段产物和任务记录，但不会删除 Ozon 店铺中已经发布的商品。`))return;try{const result=await api('/api/pipelines/batch-delete',{method:'POST',body:JSON.stringify({pipeline_ids:unique,confirm_delete:true})});const removed=new Set(result.deleted||[]);state.selectedPipelineIds=new Set([...state.selectedPipelineIds].filter(id=>!removed.has(id)));state.selectedCatalogIds=new Set([...state.selectedCatalogIds].filter(id=>!removed.has(id)));if(state.current&&removed.has(String(state.current.pipeline_id)))state.current=null;await load();await loadCatalog();renderTaskCenter();toast(`已删除 ${removed.size} 个本地商品任务${result.blocked?.length?`，${result.blocked.length} 个正在运行未删除`:''}`,Boolean(result.blocked?.length))}catch(error){toast(error.message,true)}}
function renderDetail(){if(!state.current){$('#emptyState').classList.remove('hidden');$('#detail').classList.add('hidden');return}$('#emptyState').classList.add('hidden');$('#detail').classList.remove('hidden');$('#productId').textContent=`1688 · ${state.current.pipeline_id}`;$('#productTitle').textContent=state.current.title_zh||'商品上架流水线';const selected=state.stores.find(store=>store.store_id===state.current.store_id);const statuses=stages.map(stage=>stageStatus(state.current,stage.n));const done=statuses.filter(status=>status==='PASS').length;const failed=statuses.includes('FAIL');const running=statuses.includes('RUNNING');const overall=$('#overallState');overall.textContent=failed?'需要处理':running?'正在运行':done===5?'上架完成':`${done}/5 已通过`;overall.className=`health-pill ${failed?'bad':running?'running':done===5?'good':''}`;$('#progressMetric').textContent=`${done} / 5`;$('#progressHint').textContent=done===5?'全部阶段已通过':failed?'存在门禁失败':`下一步：阶段 ${Math.min(done+1,5)}`;$('#storeMetric').textContent=selected?selected.name:state.stores.length?`${state.stores.length} 个店铺`:'未授权';$('#modeMetric').textContent=state.config?.dry_run?'DRY RUN':'LIVE';$('#modeHint').textContent=state.config?.dry_run?'安全预演，不提交':'允许真实提交';$('#updatedMetric').textContent=formatDate(state.current.updated_at);$('#configStrip').innerHTML=`<span><b>运行模式</b> ${state.config?.dry_run?'DRY RUN · 安全预演':'LIVE · 允许真实提交'}</span><span><b>OZON 店铺</b> ${selected?escapeHtml(selected.name):state.stores.length?`${state.stores.length} 个已授权 · 尚未选择`:'未授权'}</span><span><b>任务目录</b> work/${escapeHtml(state.current.pipeline_id)}/</span>`;$('#stageGrid').innerHTML=stages.map(s=>{const status=stageStatus(state.current,s.n);const artifact=state.current.artifacts?.[String(s.n)];return `<article class="stage stage-${status.toLowerCase()}"><div class="stage-number">0${s.n}<span class="status ${status.toLowerCase()}">${status}</span></div><h3>${s.title}</h3><p>${s.desc}</p><div class="stage-actions"><button data-run="${s.n}" ${canRun(s.n)?'':'disabled'}>${status==='LOCKED'?'开始运行':status==='RUNNING'?'运行中':'重新运行'}</button>${artifact?`<button class="view" data-view="${s.n}">查看产物</button>`:''}${s.n===1&&artifact?'<button class="view" data-skus>管理 SKU</button><button class="view" data-images>管理图片</button>':''}</div></article>`}).join('');document.querySelectorAll('[data-run]').forEach(button=>button.onclick=()=>openStage(Number(button.dataset.run)));document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>viewArtifact(Number(button.dataset.view)));document.querySelectorAll('[data-skus]').forEach(button=>button.onclick=openSkuManager);document.querySelectorAll('[data-images]').forEach(button=>button.onclick=openImages);const issues=(state.dashboard.issues||[]).filter(issue=>String(issue.pipeline_id)===String(state.current.pipeline_id));const card=$('#diagnosisCard');card.classList.toggle('hidden',!issues.length);$('#diagnosisCount').textContent=`${issues.length} 项`;$('#diagnosisList').innerHTML=issues.map(issue=>`<article class="diagnosis-item"><span class="diagnosis-tag">${escapeHtml(issue.category)}</span><div class="diagnosis-body"><b>阶段 ${issue.stage} · ${escapeHtml(issue.message)}</b><span>建议：${escapeHtml(issue.suggestion)}</span></div><button class="diagnosis-action" data-diagnosis-stage="${issue.stage}">打开阶段</button></article>`).join('');document.querySelectorAll('[data-diagnosis-stage]').forEach(button=>button.onclick=()=>openStage(Number(button.dataset.diagnosisStage)))}

const roleName=role=>({images:'主图',detail_images:'详情图',sku_image:'SKU 图'}[role]||role);
const actionName=action=>({exclude:'排除',translate:'图片翻译模型 → 俄语 Rich Content',reference_8:'参考生成共用八图',sku_main:'生成 SKU 专属主图'}[action]||action);
function renderImageGallery(){const selected=state.imageSelection.filter(item=>item.action!=='exclude').length;const aiCalls=state.imageSelection.reduce((sum,item)=>sum+(item.action==='reference_8'?8:item.action==='sku_main'?1:0),0);const translateCalls=state.imageSelection.filter(item=>item.action==='translate').length;$('#imageSelectionCount').textContent=`已处理 ${selected} / ${state.imageSelection.length} 张 · AI 生图 ${aiCalls} 次 · 翻译 ${translateCalls} 次`;$('#imageGallery').innerHTML=state.imageSelection.map((item,index)=>`<article class="image-card ${item.action!=='exclude'?'selected':'removed'}"><img src="${escapeHtml(item.url)}" alt="${escapeHtml(roleName(item.source_role))}" loading="lazy" referrerpolicy="no-referrer"><div class="image-card-body"><span>${escapeHtml(roleName(item.source_role))}${item.sku_id?` · SKU ${escapeHtml(item.sku_id)}`:''}</span><small>${escapeHtml(item.width||'?')} × ${escapeHtml(item.height||'?')} · ${escapeHtml(actionName(item.action))}</small><select class="image-action" data-image-index="${index}"><option value="exclude" ${item.action==='exclude'?'selected':''}>排除，不处理</option><option value="translate" ${item.action==='translate'?'selected':''}>独立图片翻译模型 → 俄语 Rich Content</option><option value="reference_8" ${item.action==='reference_8'?'selected':''}>作为参考生成共用八图</option>${item.source_role==='sku_image'?`<option value="sku_main" ${item.action==='sku_main'?'selected':''}>生成 SKU 专属主图</option>`:''}</select></div></article>`).join('');document.querySelectorAll('[data-image-index]').forEach(select=>select.onchange=()=>{const index=Number(select.dataset.imageIndex);if(select.value==='reference_8')state.imageSelection.forEach((item,itemIndex)=>{if(itemIndex!==index&&item.action==='reference_8')item.action='exclude'});state.imageSelection[index].action=select.value;renderImageGallery()})}
async function openImages(){try{const result=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/images`);state.imageSelection=result.images||[];renderImageGallery();$('#imagesDialog').showModal()}catch(error){toast(error.message,true)}}
async function saveImages(){try{const imagePlan=state.imageSelection.map(item=>({url:item.url,sku_id:item.sku_id||null,action:item.action}));const result=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/images`,{method:'POST',body:JSON.stringify({image_plan:imagePlan})});state.imageSelection=result.images||[];$('#imagesDialog').close();await selectPipeline(state.current.pipeline_id);toast(`图片方案已保存：AI 生图 ${result.estimated_ai_calls} 次，翻译 ${result.estimated_translation_calls} 次`)}catch(error){toast(error.message,true)}}
function renderGeneratedImageReview(){const images=(state.imageReview?.localized_images||[]).filter(item=>item?.generation_provider==='AI_RELAY'&&item.final_public_url);const review=state.imageReview?.image_review||{};$('#imageReviewCount').textContent=`待审核 ${images.length} 张 AI 图片`;$('#imageReviewStatus').textContent=review.status==='APPROVED'?'已审核写入 ERP':review.status==='REJECTED'?'已退回':'等待人工确认';$('#imageReviewConfirm').checked=review.status==='APPROVED';$('#imageReviewGallery').innerHTML=images.map((item,index)=>`<article class="image-card selected"><span class="review-image-number">${escapeHtml(item.sku_id?`SKU ${item.sku_id}`:`第 ${item.module_number||index+1} 张`)}</span><a href="${escapeHtml(item.final_public_url)}" target="_blank" rel="noopener noreferrer"><img src="${escapeHtml(item.final_public_url)}" alt="AI 商品图 ${index+1}" loading="lazy" referrerpolicy="no-referrer"></a><div class="image-card-body"><span>${escapeHtml(item.image_usage||'商品图')}</span><small>${escapeHtml(item.width||'?')} × ${escapeHtml(item.height||'?')} · ${escapeHtml(item.aspect_ratio||'?')}</small></div></article>`).join('')||'<div class="warning danger">尚未生成可审核的 AI 图片。</div>'}
async function openGeneratedImageReview(){try{state.imageReview=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/artifacts/3`);renderGeneratedImageReview();$('#imageReviewDialog').showModal()}catch(error){toast(error.message,true)}}
async function submitImageReview(decision){if(decision==='approve'&&!$('#imageReviewConfirm').checked){toast('请先逐张检查并勾选主体一致确认',true);return}if(decision==='regenerate'&&!confirm('确认审核不通过？现有图片会保留用于审计，再次运行第三阶段时将重新生成8张图片。'))return;try{const result=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/images/review`,{method:'POST',body:JSON.stringify({decision,confirm_subject_unchanged:decision==='approve'&&$('#imageReviewConfirm').checked})});$('#imageReviewDialog').close();await selectPipeline(state.current.pipeline_id);if(decision==='approve')toast(result.status==='PASS'?'图片审核通过，已写入 ERP 并解锁第四阶段':`图片已确认，但仍有门禁：${(result.failures||[]).join('；')}`,result.status!=='PASS');else toast('图片已退回；请重新运行第三阶段生成新八图',true)}catch(error){toast(error.message,true)}}
function renderSkuManager(){const rows=(state.skuSource?.sku_list||[]).filter(item=>item&&item.sku_id!=null);const excluded=new Set((state.current?.product_settings?.excluded_sku_ids||[]).map(String));const activeCount=rows.filter(item=>!excluded.has(String(item.sku_id))).length;$('#skuManagerSummary').innerHTML=`<strong>保留 ${activeCount} / ${rows.length} 个 SKU</strong><span>已排除 ${rows.length-activeCount} 个</span>`;$('#skuManagerList').innerHTML=rows.map(item=>{const id=String(item.sku_id);const isExcluded=excluded.has(id);const specs=item.specification_text_zh||((item.specification_zh||[]).map(part=>`${part.name||''}:${part.value||''}`).join('；'))||'默认规格';const image=item.image_url?`<img src="${escapeHtml(item.image_url)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:'<span class="sku-placeholder">无图</span>';return `<article class="sku-manager-row ${isExcluded?'excluded':''}">${image}<div><b>SKU ${escapeHtml(id)}</b><small>${escapeHtml(specs)}</small><small>采集价 ¥${escapeHtml(item.purchase_price_cny??'—')} · 库存 ${escapeHtml(item.stock??'—')}</small></div><button type="button" data-sku-toggle="${escapeHtml(id)}" data-excluded="${isExcluded?'true':'false'}" ${hasPermission('stage.run')?'':'disabled'}>${isExcluded?'恢复':'删除'}</button></article>`}).join('')||'<div class="empty">没有采集到 SKU。</div>';document.querySelectorAll('[data-sku-toggle]').forEach(button=>button.onclick=()=>toggleSku(button.dataset.skuToggle,button.dataset.excluded==='true'))}
async function openSkuManager(){try{state.skuSource=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/artifacts/1`);renderSkuManager();$('#skuDialog').showModal()}catch(error){toast(error.message,true)}}
async function toggleSku(skuId,isExcluded){if(!isExcluded&&!confirm(`确认从本次上架任务中删除 SKU ${skuId}？\n\n不会删除 1688 原始采集资料，也不会自动删除 Ozon 已发布商品。`))return;try{const path=`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/skus/${encodeURIComponent(skuId)}${isExcluded?'/restore':''}`;await api(path,{method:isExcluded?'POST':'DELETE',body:isExcluded?'{}':undefined});state.current=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}`);renderSkuManager();renderDetail();toast(isExcluded?'SKU 已恢复，可参与上架':'SKU 已删除，不再参与上架')}catch(error){toast(error.message,true)}}
function renderStores(){
  $('#storeCount').textContent=state.stores.length;const root=$('#storeList');
  if(!state.stores.length){root.innerHTML='<div class="store-empty">尚未授权店铺。凭证验证成功后才能运行 OZON 类目映射。</div>';return}
  root.innerHTML=state.stores.map(store=>`<article class="store-item"><div><strong>${escapeHtml(store.name)}</strong><span>${escapeHtml(store.store_id)} · Client-Id ${escapeHtml(store.client_id)} · ${escapeHtml(store.currency_code)}</span><small>✓ 已验证 ${escapeHtml(store.verified_at||'')}</small></div><div class="store-actions"><button type="button" data-verify-store="${escapeHtml(store.store_id)}">重新验证</button><button type="button" class="danger-link" data-delete-store="${escapeHtml(store.store_id)}">删除</button></div></article>`).join('');
  root.querySelectorAll('[data-verify-store]').forEach(button=>button.onclick=()=>verifyStore(button.dataset.verifyStore));root.querySelectorAll('[data-delete-store]').forEach(button=>button.onclick=()=>deleteStore(button.dataset.deleteStore));
}
function usageLabel(key){return{products:'商品任务',stores:'授权店铺',ai_images:'AI 生图',members:'团队成员'}[key]||key}
function renderTeam(){const accounts=state.registrations.accounts||[];$('#teamCount').textContent=`${accounts.length} 人`;$('#teamList').innerHTML=accounts.length?accounts.map(account=>{const status=account.authorized?'已授权':'已解除授权';const actions=account.is_owner?'<span class="owner-chip">主账号</span>':`<div class="registration-actions"><button type="button" class="${account.authorized?'warning-link':'authorize-link'}" data-account-action="${account.authorized?'revoke':'authorize'}" data-account-user="${escapeHtml(account.username)}">${account.authorized?'解除授权':'授权'}</button><button type="button" class="danger-link" data-delete-account="${escapeHtml(account.username)}">删除</button></div>`;return`<article class="registration-row ${account.authorized?'authorized':'revoked'}"><div class="team-avatar">${escapeHtml((account.display_name||account.username).slice(0,1).toUpperCase())}</div><div><b>${escapeHtml(account.display_name||account.username)} <span class="account-state ${account.authorized?'active':'disabled'}">${status}</span></b><small>${escapeHtml(account.identifier)} · ${escapeHtml(account.role_name)} · ${escapeHtml(account.store_count)} 个店铺</small><small>注册 ${formatDate(account.created_at)} · 最近登录 ${formatDate(account.last_login_at)}</small></div>${actions}</article>`}).join(''):'<div class="store-empty">暂无注册用户。</div>';$('#teamForm').classList.add('hidden');document.querySelectorAll('[data-account-action]').forEach(button=>button.onclick=()=>setRegistrationAuthorization(button.dataset.accountUser,button.dataset.accountAction));document.querySelectorAll('[data-delete-account]').forEach(button=>button.onclick=()=>deleteRegistration(button.dataset.deleteAccount))}
function operationsStoreOptions(){return state.stores.length?state.stores.map(store=>`<option value="${escapeHtml(store.store_id)}">${escapeHtml(store.name)} · ${escapeHtml(store.currency_code)}</option>`).join(''):'<option value="">请先授权 Ozon 店铺</option>'}
function renderOperations(){const data=state.operations;if(!data)return;$('#operationsEmpty').classList.add('hidden');$('#operationsContent').classList.remove('hidden');const revenue=Object.entries(data.summary.revenue||{}).map(([currency,value])=>`${Number(value).toLocaleString('zh-CN')} ${currency}`).join(' / ')||'0 RUB';$('#operationsMetrics').innerHTML=[['订单',data.summary.orders,`${data.period_days} 天`],['销售额',revenue,'已排除取消订单'],['异常订单',data.summary.exceptions,'需人工检查'],['低库存',data.summary.low_stock,`可售 ≤ ${data.low_stock_threshold??5}`]].map(([label,value,hint])=>`<article><span>${label}</span><strong>${escapeHtml(value)}</strong><small>${hint}</small></article>`).join('');const warnings=data.warnings||[];$('#operationsWarnings').classList.toggle('hidden',!warnings.length);$('#operationsWarnings').innerHTML=warnings.map(item=>`<p>${escapeHtml(item)}</p>`).join('');$('#exceptionCount').textContent=`${data.exceptions.length} 单`;$('#exceptionList').innerHTML=data.exceptions.length?data.exceptions.map(order=>`<article><span>${escapeHtml(order.scheme)}</span><div><b>${escapeHtml(order.posting_number)}</b><small>${escapeHtml(order.status)} · ${escapeHtml(formatDate(order.created_at))}</small></div><strong>${escapeHtml(order.quantity)} 件</strong></article>`).join(''):'<div class="empty">当前时间范围内没有异常订单。</div>';$('#lowStockCount').textContent=`${data.low_stocks.length} 个`;$('#lowStockTable').innerHTML=data.low_stocks.length?data.low_stocks.map(item=>`<tr><td>${escapeHtml(item.offer_id)}</td><td>${item.present}</td><td>${item.reserved}</td><td><b class="stock-low">${item.available}</b></td></tr>`).join(''):'<tr><td colspan="4" class="table-empty">没有低库存 SKU</td></tr>';const profit=data.profit||{};const profitReady=profit.status==='READY';$('#profitCard').innerHTML=`<div class="data-card-head"><div><span class="eyebrow">ESTIMATED PROFIT</span><h2>预估利润</h2></div><span class="${profitReady?'profit-ready':'profit-blocked'}">${profitReady?'可计算':'待完善'}</span></div><div class="profit-value">${profitReady?`${Number(profit.estimated_profit_cny).toLocaleString('zh-CN')} CNY`:'—'}</div><p>${escapeHtml(profitReady?`总成本 ${Number(profit.total_cost_cny).toLocaleString('zh-CN')} CNY · 已含头程、佣金、退货、提现、广告和尾程`:(profit.reason||'缺少经营参数'))}</p>${profit.missing_cost_offer_ids?.length?`<small>缺采购价：${escapeHtml(profit.missing_cost_offer_ids.join('、'))}</small>`:''}`;const logistics=data.logistics_alerts||[];$('#logisticsCount').textContent=`${logistics.length} 单`;$('#logisticsList').innerHTML=logistics.length?logistics.map(order=>`<article class="logistics-${escapeHtml(order.severity)}"><span>${escapeHtml(order.scheme)}</span><div><b>${escapeHtml(order.posting_number)}</b><small>${escapeHtml(order.status)} · ${escapeHtml(formatDate(order.shipment_date))}</small></div><strong>${order.hours_left<0?`逾期 ${Math.abs(order.hours_left)}h`:`${order.hours_left}h`}</strong></article>`).join(''):'<div class="empty">未发现 24 小时内的发货风险。</div>';const procurement=data.procurement||[];$('#procurementCount').textContent=`${procurement.length} 个 SKU`;$('#procurementTable').innerHTML=procurement.length?procurement.map(item=>`<tr><td><b>${escapeHtml(item.offer_id)}</b></td><td>${item.sold_units}</td><td>${item.daily_sales}</td><td>${item.available}</td><td>${item.target_stock}</td><td><b class="stock-low">${item.reorder_quantity}</b></td><td>${item.purchase_total_cny==null?'<span class="cost-missing">缺采购价</span>':`${Number(item.purchase_total_cny).toLocaleString('zh-CN')} CNY`}</td></tr>`).join(''):'<tr><td colspan="7" class="table-empty">当前无需补货</td></tr>';$('#orderCount').textContent=`${data.orders.length} 单`;$('#ordersTable').innerHTML=data.orders.length?data.orders.map(order=>`<tr><td><b>${escapeHtml(order.posting_number)}</b></td><td><span class="scheme-chip">${escapeHtml(order.scheme)}</span></td><td>${escapeHtml(order.status)}</td><td>${order.quantity} 件 / ${order.product_count} 款</td><td>${escapeHtml(order.warehouse)}</td><td>${Number(order.revenue).toLocaleString('zh-CN')} ${escapeHtml(order.currency_code)}</td><td>${escapeHtml(formatDate(order.created_at))}</td></tr>`).join(''):'<tr><td colspan="7" class="table-empty">当前时间范围内没有订单</td></tr>';$('#stockCount').textContent=`${data.stocks.length} 个 SKU`;$('#stocksTable').innerHTML=data.stocks.length?data.stocks.map(item=>`<tr><td><b>${escapeHtml(item.offer_id)}</b></td><td>${escapeHtml(item.product_id||'—')}</td><td>${escapeHtml(item.sku||'—')}</td><td>${item.warehouses}</td><td>${item.present}</td><td>${item.reserved}</td><td class="${item.available<=5?'stock-low':''}">${item.available}</td></tr>`).join(''):'<tr><td colspan="7" class="table-empty">未读取到库存数据</td></tr>'}
async function loadOperations(){const button=$('#refreshOperationsBtn');const storeId=$('#operationsStore').value;if(!storeId){toast('请先授权并选择 Ozon 店铺',true);return}button.disabled=true;button.textContent='正在同步…';try{state.operations=await api(`/api/operations?store_id=${encodeURIComponent(storeId)}&days=${encodeURIComponent($('#operationsDays').value)}`);renderOperations();toast('订单与库存同步完成')}catch(error){toast(error.message,true)}finally{button.disabled=false;button.textContent='同步最新数据'}}
function populateFinanceFields(value){$('#financeRate').value=value.cny_to_rub_rate;$('#financeCommission').value=value.commission_percent;$('#financeReturns').value=value.return_loss_percent;$('#financeWithdrawal').value=value.withdrawal_percent;$('#financeAdvertising').value=value.advertising_percent;$('#financeLastMile').value=value.last_mile_percent;$('#financeTarget').value=value.target_margin_percent;$('#financeMisc').value=value.domestic_misc_cny;$('#financeLogisticsMode').value=value.logistics_mode;$('#financePostalTransport').value=value.postal_transport;$('#financeLeadTime').value=value.lead_time_days;$('#financeSafetyStock').value=value.safety_stock_days}
async function openFinanceSettings(){const storeId=$('#operationsStore').value;if(!storeId){toast('请先选择 Ozon 店铺',true);return}try{const result=await api(`/api/finance-settings?store_id=${encodeURIComponent(storeId)}`);populateFinanceFields(result.settings);$('#saveFinanceBtn').classList.toggle('hidden',!hasPermission('finance.manage'));$('#financeDialog').showModal()}catch(error){toast(error.message,true)}}
function financePayload(){return{cny_to_rub_rate:Number($('#financeRate').value),commission_percent:Number($('#financeCommission').value),return_loss_percent:Number($('#financeReturns').value),withdrawal_percent:Number($('#financeWithdrawal').value),advertising_percent:Number($('#financeAdvertising').value),last_mile_percent:Number($('#financeLastMile').value),target_margin_percent:Number($('#financeTarget').value),domestic_misc_cny:Number($('#financeMisc').value),logistics_mode:$('#financeLogisticsMode').value,postal_transport:$('#financePostalTransport').value,lead_time_days:Number($('#financeLeadTime').value),safety_stock_days:Number($('#financeSafetyStock').value)}}
async function saveFinanceSettings(event){event.preventDefault();if(!hasPermission('finance.manage')){toast('当前角色无权修改经营参数',true);return}try{await api('/api/finance-settings',{method:'POST',body:JSON.stringify({store_id:$('#operationsStore').value,settings:financePayload()})});$('#financeDialog').close();toast('经营参数已保存');await loadOperations()}catch(error){toast(error.message,true)}}
function pricingCategoryRate(item){const goodsValue=Number($('#pricingSale').value||0)*Number($('#pricingRate').value||0);return Number(item.rates[goodsValue<=1500?0:goodsValue<=5000?1:2])}
function syncPricingCategoryRate(){if(!selectedPricingCategory)return;const rate=pricingCategoryRate(selectedPricingCategory);$('#pricingCommission').value=rate;const goodsValue=Number($('#pricingSale').value||0)*Number($('#pricingRate').value||0);const band=goodsValue<=1500?'≤1500₽':goodsValue<=5000?'1500.01–5000₽':'>5000₽';$('#pricingCategoryHint').textContent=`已选：${selectedPricingCategory.main_zh} / ${selectedPricingCategory.sub_zh} / ${selectedPricingCategory.type_zh} · 当前 ${band} 佣金 ${rate}% · 三档 ${selectedPricingCategory.rates.join('% / ')}%`}
function clearPricingCategory(resetText=false){selectedPricingCategory=null;$('#pricingCategoryId').value='';$('#pricingCommission').readOnly=false;if(resetText)$('#pricingCategorySearch').value='';$('#pricingCategoryHint').textContent='请从搜索结果选择完整类目；未选择时使用下方手动佣金。'}
function renderPricingCategoryResults(){const root=$('#pricingCategoryResults');root.classList.toggle('hidden',!pricingCategoryRows.length);root.innerHTML=pricingCategoryRows.map(item=>`<button type="button" data-pricing-category="${escapeHtml(item.id)}"><b>${escapeHtml(item.type_zh)} · ${escapeHtml(item.type_ru)}</b><small>${escapeHtml(item.main_zh)} / ${escapeHtml(item.sub_zh)}</small><em>${item.rates.map(rate=>`${escapeHtml(rate)}%`).join(' / ')}</em></button>`).join('');root.querySelectorAll('[data-pricing-category]').forEach(button=>button.onclick=()=>{const item=pricingCategoryRows.find(row=>row.id===button.dataset.pricingCategory);if(!item)return;selectedPricingCategory=item;$('#pricingCategoryId').value=item.id;$('#pricingCategorySearch').value=`${item.type_zh} · ${item.main_zh} / ${item.sub_zh}`;$('#pricingCommission').readOnly=true;root.classList.add('hidden');syncPricingCategoryRate()})}
async function searchPricingCategories(query){if(query.length<1){pricingCategoryRows=[];renderPricingCategoryResults();return}try{const result=await api(`/api/pricing/categories?q=${encodeURIComponent(query)}&limit=30`);pricingCategoryRows=result.results||[];renderPricingCategoryResults();if(!pricingCategoryRows.length)$('#pricingCategoryHint').textContent='未找到匹配类目，请换一个中文或俄文关键词'}catch(error){toast(error.message,true)}}
async function loadPricingSettings(){const storeId=$('#pricingStore').value;if(!storeId){toast('请先选择 Ozon 店铺',true);return}try{const value=(await api(`/api/finance-settings?store_id=${encodeURIComponent(storeId)}`)).settings;$('#pricingRate').value=value.cny_to_rub_rate;$('#pricingCommission').value=value.commission_percent;$('#pricingReturns').value=value.return_loss_percent;$('#pricingWithdrawal').value=value.withdrawal_percent;$('#pricingAdvertising').value=value.advertising_percent;$('#pricingLastMile').value=value.last_mile_percent;$('#pricingTarget').value=value.target_margin_percent;$('#pricingMisc').value=value.domestic_misc_cny;$('#pricingMode').value=value.logistics_mode;$('#pricingTransport').value=value.postal_transport;clearPricingCategory(true);$('#pricingCommission').value=value.commission_percent;toast('已读取店铺定价参数')}catch(error){toast(error.message,true)}}
function pricingPayload(){return{sale_price_cny:Number($('#pricingSale').value),purchase_cost_cny:Number($('#pricingPurchase').value),domestic_misc_cny:Number($('#pricingMisc').value),commission_category_id:$('#pricingCategoryId').value,commission_percent:Number($('#pricingCommission').value),return_loss_percent:Number($('#pricingReturns').value),withdrawal_percent:Number($('#pricingWithdrawal').value),advertising_percent:Number($('#pricingAdvertising').value),last_mile_percent:Number($('#pricingLastMile').value),target_margin_percent:Number($('#pricingTarget').value),weight_g:Number($('#pricingWeight').value),length_cm:Number($('#pricingLength').value),width_cm:Number($('#pricingWidth').value),height_cm:Number($('#pricingHeight').value),cny_to_rub_rate:Number($('#pricingRate').value),logistics_mode:$('#pricingMode').value,postal_transport:$('#pricingTransport').value}}
async function calculatePricing(event){event.preventDefault();try{const result=(await api('/api/pricing/calculate',{method:'POST',body:JSON.stringify(pricingPayload())})).calculation;const fees=result.fees;$('#pricingResults').innerHTML=`<div class="pricing-result-head"><span>${escapeHtml(result.channel)}</span><small>计费重 ${Number(result.charge_weight_g).toLocaleString('zh-CN')}g · 货值 ${Number(result.goods_value_rub).toLocaleString('zh-CN')}₽</small></div><div class="pricing-hero-result"><span>建议售价</span><strong>¥${Number(result.suggested_price_cny).toLocaleString('zh-CN')}</strong><small>保本价 ¥${Number(result.break_even_price_cny).toLocaleString('zh-CN')}</small></div><div class="pricing-kpis"><article><span>单件利润</span><b>¥${Number(result.unit_profit_cny).toLocaleString('zh-CN')}</b></article><article><span>销售毛利率</span><b>${escapeHtml(result.sales_margin_percent)}%</b></article><article><span>总成本</span><b>¥${Number(result.total_cost_cny).toLocaleString('zh-CN')}</b></article></div><div class="fee-breakdown">${[['采购成本',fees.purchase_cost],['国内杂费',fees.domestic_misc],['头程物流',fees.first_mile_logistics],['平台佣金',fees.platform_commission],['退货/取消',fees.return_cancel_loss],['提现/结汇',fees.withdrawal_exchange],['广告费',fees.advertising],['尾程配送',fees.last_mile_delivery]].map(([label,value])=>`<div><span>${label}</span><b>¥${Number(value).toLocaleString('zh-CN')}</b></div>`).join('')}</div>${result.warnings.length?`<div class="pricing-warnings">${result.warnings.map(item=>`<p>${escapeHtml(item)}</p>`).join('')}</div>`:''}`;toast('定价试算完成')}catch(error){toast(error.message,true)}}
function renderPricingCalculation(result){const fees=result.fees;const commission=result.commission||{};const category=commission.category;const categoryLabel=category?`${category.main_zh} / ${category.sub_zh} / ${category.type_zh}`:'手动佣金';$('#pricingResults').innerHTML=`<div class="pricing-result-head"><span>${escapeHtml(result.channel)} · 佣金 ${escapeHtml(commission.applied_percent||'')}%</span><small>${escapeHtml(categoryLabel)}<br>计费重 ${Number(result.charge_weight_g).toLocaleString('zh-CN')}g · 货值 ${Number(result.goods_value_rub).toLocaleString('zh-CN')}₽ · ${escapeHtml(commission.price_band||'')}</small></div><div class="pricing-hero-result"><span>建议售价</span><strong>¥${Number(result.suggested_price_cny).toLocaleString('zh-CN')}</strong><small>保本价 ¥${Number(result.break_even_price_cny).toLocaleString('zh-CN')}</small></div><div class="pricing-kpis"><article><span>单件利润</span><b>¥${Number(result.unit_profit_cny).toLocaleString('zh-CN')}</b></article><article><span>销售毛利率</span><b>${escapeHtml(result.sales_margin_percent)}%</b></article><article><span>总成本</span><b>¥${Number(result.total_cost_cny).toLocaleString('zh-CN')}</b></article></div><div class="fee-breakdown">${[['采购成本',fees.purchase_cost],['国内杂费',fees.domestic_misc],['头程物流',fees.first_mile_logistics],['平台佣金',fees.platform_commission],['退货/取消',fees.return_cancel_loss],['提现/结汇',fees.withdrawal_exchange],['广告费',fees.advertising],['尾程配送',fees.last_mile_delivery]].map(([label,value])=>`<div><span>${label}</span><b>¥${Number(value).toLocaleString('zh-CN')}</b></div>`).join('')}</div>${result.warnings.length?`<div class="pricing-warnings">${result.warnings.map(item=>`<p>${escapeHtml(item)}</p>`).join('')}</div>`:''}`}
async function calculatePricingV2(event){event.preventDefault();try{const result=(await api('/api/pricing/calculate',{method:'POST',body:JSON.stringify(pricingPayload())})).calculation;renderPricingCalculation(result);toast(`定价试算完成 · 当前佣金 ${result.commission.applied_percent}%`)}catch(error){toast(error.message,true)}}
function taskStage(pipeline){for(let n=1;n<=5;n++){const status=stageStatus(pipeline,n);if(status==='FAIL'||status==='RUNNING'||status==='LOCKED')return n}return 5}
function taskStatusName(bucket){return{completed:'已完成',failed:'门禁失败',running:'运行中',draft:'待处理'}[bucket]||bucket}
function activityName(item){const path=String(item.path||'');if(path==='/api/pipelines')return'创建并采集商品';if(path==='/api/batch-imports')return'创建批量采集任务';if(path==='/api/batch-processes')return'创建批量商品处理任务';if(path==='/api/supplier-monitor')return'创建供应商变更检测任务';if(path==='/api/supplier-monitor/schedule')return item.method==='DELETE'?'删除供应商检测计划':'修改供应商检测计划';if(path==='/api/products/batch-edit')return'批量编辑商品参数';if(/\/versions\/[a-f0-9]{24}\/restore$/.test(path))return'回滚商品参数版本';if(/\/skus\/[^/]+\/restore$/.test(path))return'恢复采集 SKU';if(/\/skus\/[^/]+$/.test(path)&&item.method==='DELETE')return'删除采集 SKU';if(/^\/api\/assets\//.test(path)&&item.method==='DELETE')return'清理 OSS 图片资产';if(/\/stages\/(\d+)$/.test(path))return`运行阶段 ${path.match(/\/stages\/(\d+)$/)[1]}`;if(path.endsWith('/images'))return'保存图片处理方案';if(path==='/api/stores')return'新增店铺授权';if(/^\/api\/stores\/[^/]+$/.test(path)&&item.method==='DELETE')return'删除店铺授权';if(path.includes('/verify'))return'验证店铺授权';if(/^\/api\/registrations\/[^/]+\/authorize$/.test(path))return'授权注册账号';if(/^\/api\/registrations\/[^/]+\/revoke$/.test(path))return'解除注册账号授权';if(/^\/api\/registrations\/[^/]+$/.test(path)&&item.method==='DELETE')return'删除注册账号';if(path==='/api/finance-settings')return'修改经营参数';if(path==='/api/notifications/read')return'标记失败通知已读';if(path==='/api/ai-provider')return item.method==='DELETE'?'删除 AI 配置':'修改 AI 配置';if(path==='/api/object-storage')return item.method==='DELETE'?'删除图片存储配置':'修改图片存储配置';if(path==='/api/team'||/^\/api\/team\/[^/]+$/.test(path))return'修改团队成员';return`${item.method} ${path}`}
function renderTaskCenter(){const counters=state.dashboard.counters||{};$('#taskMetrics').innerHTML=[['全部任务',counters.total||0,'所有商品流水线'],['运行中',counters.running||0,'后台任务'],['门禁失败',counters.failed||0,'需要人工处理'],['已完成',counters.completed||0,'五阶段通过']].map(([label,value,hint])=>`<article><span>${label}</span><strong>${value}</strong><small>${hint}</small></article>`).join('');const alerts=[];if(!state.stores.length)alerts.push({level:'critical',title:'尚未授权 Ozon 店铺',detail:'类目、属性和真实上架均不可用'});if(!(state.aiProvider?.text_api_key_configured&&state.aiProvider?.image_api_key_configured))alerts.push({level:'warning',title:'AI 服务配置不完整',detail:'俄语文案或 AI 生图可能无法执行'});if(counters.failed)alerts.push({level:'critical',title:`${counters.failed} 个商品存在门禁失败`,detail:'请从下方队列打开对应商品修复'});if(state.config?.dry_run)alerts.push({level:'info',title:'当前处于 DRY RUN',detail:'第五阶段只预演，不会真实提交至 Ozon'});if(!alerts.length)alerts.push({level:'success',title:'系统运行正常',detail:'暂未发现配置或流水线告警'});$('#alertCount').textContent=`${alerts.length} 项`;$('#systemAlerts').innerHTML=alerts.map(item=>`<article class="alert-${item.level}"><i></i><div><b>${escapeHtml(item.title)}</b><small>${escapeHtml(item.detail)}</small></div></article>`).join('');const rows=state.pipelines.filter(item=>state.taskFilter==='all'||pipelineBucket(item)===state.taskFilter);$('#taskCount').textContent=`${rows.length} / ${state.pipelines.length}`;$('#taskTable').innerHTML=rows.length?rows.map(item=>{const bucket=pipelineBucket(item);const done=Object.values(item.stages||{}).filter(stage=>stage.status==='PASS').length;const current=taskStage(item);const failure=item.stages?.[String(current)]?.failures?.[0]||'—';return`<tr><td><b>${escapeHtml(item.pipeline_id)}</b></td><td><span class="task-status ${bucket}">${taskStatusName(bucket)}</span></td><td><div class="mini-progress"><i class="progress-${done}"></i></div><small>${done}/5</small></td><td>阶段 ${current} · ${escapeHtml(stages[current-1]?.title||'')}</td><td class="task-problem">${escapeHtml(failure)}</td><td>${escapeHtml(formatDate(item.updated_at))}</td><td><button data-open-task="${escapeHtml(item.pipeline_id)}" data-task-stage="${current}">打开</button></td></tr>`}).join(''):'<tr><td colspan="7" class="table-empty">没有符合条件的任务</td></tr>';document.querySelectorAll('[data-open-task]').forEach(button=>button.onclick=async()=>{await selectPipeline(button.dataset.openTask);showWorkspace('products');const stage=Number(button.dataset.taskStage);if(state.current?.artifacts?.[String(stage)])await viewArtifact(stage)});if(!hasPermission('audit.read')){$('#activityCount').textContent='受限';$('#activityList').innerHTML='<div class="empty">仅所有者和管理员可查看操作审计。</div>'}else{const activities=state.activity||[];$('#activityCount').textContent=`${activities.length} 条`;$('#activityList').innerHTML=activities.length?activities.map(item=>`<article><span class="activity-outcome ${item.outcome==='SUCCESS'?'success':'failed'}"></span><div><b>${escapeHtml(activityName(item))}</b><small>${escapeHtml(item.actor)} · ${escapeHtml(formatDate(item.created_at))} · HTTP ${escapeHtml(item.status)}</small></div></article>`).join(''):'<div class="empty">暂无操作记录，新版部署后的修改操作会显示在这里。</div>'}}
async function loadTaskCenter(){try{await loadNotifications(false);if(hasPermission('audit.read'))state.activity=(await api('/api/activity?limit=100')).activities||[];renderTaskCenter()}catch(error){toast(error.message,true);renderTaskCenter()}}
const baseRenderTaskCenter=renderTaskCenter;
renderTaskCenter=function(){baseRenderTaskCenter();document.querySelectorAll('[data-open-task]').forEach(button=>{const pipeline=state.pipelines.find(item=>String(item.pipeline_id)===String(button.dataset.openTask));const failed=pipelineBucket(pipeline||{})==='failed';button.textContent=failed?'修复 / 重试':'打开';button.onclick=async()=>{await selectPipeline(button.dataset.openTask);showWorkspace('products');const stage=Number(button.dataset.taskStage);if(failed){await openStage(stage);if(stage===5)toast('第五阶段不会自动重试，请核对结果并再次人工确认')}else if(state.current?.artifacts?.[String(stage)])await viewArtifact(stage)}})};
const baseRenderTaskSelection=renderTaskCenter;
renderTaskCenter=function(){baseRenderTaskSelection();const rows=state.pipelines.filter(item=>state.taskFilter==='all'||pipelineBucket(item)===state.taskFilter);document.querySelectorAll('#taskTable tr').forEach((tr,index)=>{const item=rows[index];if(!item)return;tr.insertAdjacentHTML('afterbegin',`<td><input type="checkbox" data-task-select="${escapeHtml(item.pipeline_id)}" ${state.selectedPipelineIds.has(String(item.pipeline_id))?'checked':''} aria-label="选择任务 ${escapeHtml(item.pipeline_id)}"></td>`);const cell=tr.lastElementChild;if(cell)cell.insertAdjacentHTML('beforeend',`<button type="button" class="row-delete" data-delete-task="${escapeHtml(item.pipeline_id)}">删除</button>`) });document.querySelectorAll('[data-task-select]').forEach(control=>control.onchange=()=>{const id=String(control.dataset.taskSelect);control.checked?state.selectedPipelineIds.add(id):state.selectedPipelineIds.delete(id);updateTaskSelection(rows)});document.querySelectorAll('[data-delete-task]').forEach(button=>button.onclick=()=>deletePipelines([button.dataset.deleteTask]));updateTaskSelection(rows)};
function updateTaskSelection(rows=[]){const selected=state.selectedPipelineIds.size;$('#deleteSelectedTasksBtn').textContent=`删除（${selected}）`;$('#deleteSelectedTasksBtn').disabled=!selected||!hasPermission('pipeline.create');const all=rows.length>0&&rows.every(item=>state.selectedPipelineIds.has(String(item.pipeline_id)));$('#taskSelectAll').checked=all;$('#taskSelectAll').indeterminate=!all&&rows.some(item=>state.selectedPipelineIds.has(String(item.pipeline_id)))}
function renderNotifications(){const inbox=state.notifications||{notifications:[],unread_count:0};const badge=$('#notificationBadge');badge.textContent=String(inbox.unread_count||0);badge.classList.toggle('has-unread',Number(inbox.unread_count)>0);const rows=inbox.notifications||[];$('#notificationList').innerHTML=rows.length?rows.map(item=>`<button class="notification-item ${item.read?'read':'unread'}" type="button" data-notification-pipeline="${escapeHtml(item.pipeline_id)}" data-notification-stage="${escapeHtml(item.stage)}"><i></i><span><b>${escapeHtml(item.title)}</b><small>${escapeHtml(item.message)}</small><em>${item.requires_manual_confirmation?'必须人工确认真实提交':escapeHtml(item.suggestion||'打开对应阶段修复')}</em></span></button>`).join(''):'<div class="empty">当前没有门禁失败通知。</div>';document.querySelectorAll('[data-notification-pipeline]').forEach(button=>button.onclick=async()=>{const pipelineId=button.dataset.notificationPipeline;const stage=Number(button.dataset.notificationStage);$('#notificationDialog').close();await selectPipeline(pipelineId);showWorkspace('products');await openStage(stage)})}
function renderExternalAlerts(value){$('#alertsEnabled').checked=Boolean(value.enabled);$('#wecomEnabled').checked=Boolean(value.wecom_enabled);$('#wecomWebhook').value='';$('#wecomWebhook').placeholder=value.wecom_configured?'Webhook 已安全保存，留空保持不变':'https://qyapi.weixin.qq.com/cgi-bin/webhook/send?key=...';$('#emailEnabled').checked=Boolean(value.email_enabled);$('#smtpHost').value=value.smtp_host||'';$('#smtpPort').value=value.smtp_port||587;$('#smtpSecurity').value=value.smtp_security||'starttls';$('#smtpUsername').value=value.smtp_username||'';$('#smtpPassword').value='';$('#smtpPassword').placeholder=value.smtp_password_configured?'密码已安全保存，留空保持不变':'SMTP 密码或授权码';$('#emailFrom').value=value.email_from||'';$('#emailRecipients').value=(value.email_recipients||[]).join('\n');const deliveries=value.deliveries||[];$('#alertDeliveryList').innerHTML=deliveries.length?deliveries.slice(0,10).map(item=>`<article class="version-item"><div><b>${escapeHtml(item.channel)} · ${escapeHtml(item.status)}</b><small>${escapeHtml(formatDate(item.created_at))}${item.test?' · 测试通知':''}${item.error?` · ${escapeHtml(item.error)}`:''}</small></div></article>`).join(''):'<div class="store-empty">暂无外部通知发送记录。</div>'}
async function openExternalAlerts(){if(!hasPermission('team.manage')){toast('仅所有者或管理员可配置外部通知',true);return}try{const value=(await api('/api/alert-channels')).channels;renderExternalAlerts(value);$('#externalAlertsDialog').showModal()}catch(error){toast(error.message,true)}}
function externalAlertsPayload(){return{enabled:$('#alertsEnabled').checked,wecom_enabled:$('#wecomEnabled').checked,wecom_webhook_url:$('#wecomWebhook').value.trim(),email_enabled:$('#emailEnabled').checked,smtp_host:$('#smtpHost').value.trim(),smtp_port:Number($('#smtpPort').value),smtp_security:$('#smtpSecurity').value,smtp_username:$('#smtpUsername').value.trim(),smtp_password:$('#smtpPassword').value.trim(),email_from:$('#emailFrom').value.trim(),email_recipients:$('#emailRecipients').value.split(/[\n,;]+/).map(value=>value.trim()).filter(Boolean)}}
async function saveExternalAlerts(event){event.preventDefault();try{const value=(await api('/api/alert-channels',{method:'POST',body:JSON.stringify(externalAlertsPayload())})).channels;renderExternalAlerts(value);toast('外部通知配置已安全保存')}catch(error){$('#smtpPassword').value='';$('#wecomWebhook').value='';toast(error.message,true)}}
