async function deleteExternalAlerts(){if(!confirm('确认删除企业微信和邮件通知配置？发送历史也会删除。'))return;try{await api('/api/alert-channels',{method:'DELETE'});renderExternalAlerts({});$('#externalAlertsDialog').close();toast('外部通知配置已删除')}catch(error){toast(error.message,true)}}
function catalogStatusName(value){return{published:'已上架',ready:'待上架',needs_update:'需要更新',failed:'门禁失败',processing:'处理中',draft:'草稿'}[value]||value}
function catalogPrice(item){if(!item.price_min)return'—';const currency=item.currency_code||'';return item.price_min===item.price_max?`${item.price_min} ${currency}`:`${item.price_min}–${item.price_max} ${currency}`}
function filteredCatalog(){const query=state.catalogSearch.toLowerCase();return(state.productCatalog.products||[]).filter(item=>{if(state.catalogStatusFilter!=='all'&&item.status!==state.catalogStatusFilter)return false;if(!query)return true;return`${item.pipeline_id||''} ${item.title_zh||''} ${item.title_ru||''} ${(item.offer_ids||[]).join(' ')} ${item.store_id||''}`.toLowerCase().includes(query)})}
function updateCatalogSelection(){const rows=filteredCatalog();const selected=state.selectedCatalogIds.size;$('#batchProcessBtn').textContent=`批量处理（${selected}）`;$('#batchEditBtn').textContent=`批量编辑（${selected}）`;$('#supplierMonitorBtn').textContent=`供应商检测（${selected}）`;$('#deleteSelectedCatalogBtn').textContent=`删除（${selected}）`;const disabled=!selected||!hasPermission('stage.run');$('#batchProcessBtn').disabled=disabled;$('#batchEditBtn').disabled=disabled;$('#deleteSelectedCatalogBtn').disabled=!selected||!hasPermission('pipeline.create');$('#supplierMonitorBtn').disabled=!selected||!hasPermission('pipeline.create');const all=rows.length>0&&rows.every(item=>state.selectedCatalogIds.has(String(item.pipeline_id)));$('#catalogSelectAll').checked=all;$('#catalogSelectAll').indeterminate=!all&&rows.some(item=>state.selectedCatalogIds.has(String(item.pipeline_id)))}
function renderCatalog(){const summary=state.productCatalog.summary||{};$('#catalogMetrics').innerHTML=[['全部商品',summary.total||0,`${summary.sku_count||0} 个 SKU`],['已上架',summary.published||0,'Ozon 已验证'],['待上架',summary.ready||0,'Payload 已就绪'],['需要处理',(summary.failed||0)+(summary.needs_update||0),`${summary.failed||0} 失败 · ${summary.needs_update||0} 更新`]].map(([label,value,hint])=>`<article><span>${label}</span><strong>${value}</strong><small>${hint}</small></article>`).join('');const rows=filteredCatalog();$('#catalogTable').innerHTML=rows.length?rows.map(item=>`<tr><td><input type="checkbox" data-catalog-select="${escapeHtml(item.pipeline_id)}" ${state.selectedCatalogIds.has(String(item.pipeline_id))?'checked':''} aria-label="选择商品 ${escapeHtml(item.pipeline_id)}"></td><td><div class="catalog-product"><div class="catalog-thumb">${item.thumbnail_url?`<img src="${escapeHtml(item.thumbnail_url)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:'<span>无图</span>'}</div><div><b title="${escapeHtml(item.display_title)}">${escapeHtml(item.display_title)}</b><small>1688 · ${escapeHtml(item.pipeline_id)}${item.title_zh&&item.title_ru?` · ${escapeHtml(item.title_zh)}`:''}</small></div></div></td><td><span class="catalog-status ${escapeHtml(item.status)}">${escapeHtml(catalogStatusName(item.status))}</span>${item.latest_failure?`<small class="catalog-error" title="${escapeHtml(item.latest_failure)}">${escapeHtml(item.latest_failure)}</small>`:''}</td><td>${escapeHtml(item.sku_count)}</td><td>${escapeHtml(item.ozon_category_id||'—')} / ${escapeHtml(item.ozon_type_id||'—')}</td><td>${escapeHtml(catalogPrice(item))}</td><td>${escapeHtml(item.store_id||'—')}</td><td><div class="mini-progress"><i class="progress-${escapeHtml(item.stage_passed_count)}"></i></div><small>${escapeHtml(item.stage_passed_count)}/5</small></td><td>${escapeHtml(formatDate(item.updated_at))}</td><td><button type="button" data-catalog-pipeline="${escapeHtml(item.pipeline_id)}">打开</button></td></tr>`).join(''):'<tr><td colspan="10" class="table-empty">没有符合条件的商品</td></tr>';document.querySelectorAll('[data-catalog-pipeline]').forEach(button=>button.onclick=async()=>{await selectPipeline(button.dataset.catalogPipeline);showWorkspace('products')});document.querySelectorAll('[data-catalog-select]').forEach(control=>control.onchange=()=>{const id=String(control.dataset.catalogSelect);if(control.checked)state.selectedCatalogIds.add(id);else state.selectedCatalogIds.delete(id);updateCatalogSelection()});updateCatalogSelection()}
async function loadCatalog(){try{state.productCatalog=await api('/api/products');const valid=new Set((state.productCatalog.products||[]).map(item=>String(item.pipeline_id)));state.selectedCatalogIds=new Set([...state.selectedCatalogIds].filter(id=>valid.has(id)));renderCatalog()}catch(error){toast(error.message,true)}}
function supplierStatusName(value){return{QUEUED:'排队中',RUNNING:'检测中',COMPLETED:'已完成',PARTIAL:'部分失败',INTERRUPTED:'已中断',UNKNOWN:'未知',BASELINE:'已建立基线',UNCHANGED:'无变化',CHANGED:'发现变化',CHECK_FAILED:'检测失败',SCHEDULED:'已计划',DISABLED:'已停用',STARTING:'正在启动',FAILED:'失败',DEFERRED_AFTER_RESTART:'重启后已顺延'}[value]||value||'未检测'}
function renderSupplierMonitor(){const summary=state.supplierMonitor.summary||{};$('#supplierMonitorMetrics').innerHTML=[['已监控',summary.monitored||0,'商品'],['发生变化',summary.changed||0,'待人工确认'],['已断货',summary.out_of_stock||0,'全部 SKU 为零'],['检测失败',summary.failed||0,'接口或数据错误']].map(([label,value,hint])=>`<article><span>${label}</span><strong>${value}</strong><small>${hint}</small></article>`).join('');const rows=state.supplierMonitor.products||[];$('#supplierMonitorResults').innerHTML=rows.length?rows.map(item=>{const snapshot=item.snapshot||{};const details=(item.changes||[]).map(change=>change.message).join('；')||item.error||`SKU ${snapshot.sku_count||0} · ${snapshot.stock_status==='OUT_OF_STOCK'?'已断货':snapshot.stock_status==='IN_STOCK'?'有库存':'库存未知'}`;return`<article class="version-item"><div><b>${escapeHtml(item.pipeline_id)} · ${escapeHtml(supplierStatusName(item.check_status))}</b><small>${escapeHtml(details)} · ${escapeHtml(formatDate(item.checked_at))}</small></div></article>`}).join(''):'<div class="store-empty">尚未建立供应商监控基线。</div>'}
function renderSupplierSchedule(schedule){$('#supplierScheduleEnabled').checked=Boolean(schedule.enabled);$('#supplierScheduleInterval').value=String(schedule.interval_hours||24);$('#supplierScheduleProducts').value=(schedule.pipeline_ids||[]).join('\n');$('#supplierScheduleConfirm').checked=false;$('#supplierScheduleStatus').textContent=schedule.enabled?'已启用':'未启用';const latest=schedule.last_job_status?` · 最近任务：${supplierStatusName(schedule.last_job_status)}${schedule.last_job_message?`（${schedule.last_job_message}）`:''}`:'';$('#supplierScheduleInfo').textContent=schedule.enabled?`下次检测：${formatDate(schedule.next_run_at)} · 调度状态：${supplierStatusName(schedule.last_status)}${latest}${schedule.last_error?` · ${schedule.last_error}`:''}`:'定时计划未启用；保存禁用状态不会产生接口调用。'}
async function openSupplierMonitor(){if(!state.selectedCatalogIds.size){toast('请先选择商品',true);return}try{state.supplierMonitor=await api('/api/supplier-monitor');renderSupplierMonitor();$('#supplierMonitorConfirm').checked=false;const canSchedule=hasPermission('team.manage');$('#supplierSchedulePanel').classList.toggle('hidden',!canSchedule);if(canSchedule)renderSupplierSchedule((await api('/api/supplier-monitor/schedule')).schedule||{});$('#supplierMonitorDialog').showModal()}catch(error){toast(error.message,true)}}
function stopSupplierMonitorPolling(){if(state.supplierMonitorTimer){clearTimeout(state.supplierMonitorTimer);state.supplierMonitorTimer=null}}
function renderSupplierMonitorJob(job){const total=Number(job.total||0);const completed=Number(job.completed_count||0);const percent=total?Math.round(completed/total*100):0;$('#supplierMonitorResults').innerHTML=`<div class="batch-import-progress"><div><b>${escapeHtml(job.message||'正在检测')}</b><span>${completed}/${total} · ${percent}%</span></div><div class="batch-progress-track"><i style="width:${percent}%"></i></div></div>`+(job.items||[]).map(item=>`<article class="version-item"><div><b>${escapeHtml(item.pipeline_id)} · ${escapeHtml(supplierStatusName(item.status))}</b><small>${escapeHtml((item.changes||[]).map(change=>change.message).join('；')||item.error||'等待检测')}</small></div></article>`).join('')}
async function pollSupplierMonitor(jobId){stopSupplierMonitorPolling();try{const job=await api(`/api/supplier-monitor/jobs/${encodeURIComponent(jobId)}`);state.supplierMonitorJob=job;renderSupplierMonitorJob(job);if(!['COMPLETED','PARTIAL','FAILED','INTERRUPTED'].includes(job.status)){state.supplierMonitorTimer=setTimeout(()=>pollSupplierMonitor(jobId),2000);return}state.supplierMonitor=await api('/api/supplier-monitor');renderSupplierMonitor();$('#runSupplierMonitorBtn').disabled=false;$('#runSupplierMonitorBtn').textContent='检测选中商品';toast(job.message,job.status!=='COMPLETED')}catch(error){$('#runSupplierMonitorBtn').disabled=false;$('#runSupplierMonitorBtn').textContent='检测选中商品';toast(error.message,true)}}
async function runSupplierMonitor(){if(!$('#supplierMonitorConfirm').checked){toast('请先确认允许调用 AlphaShop API',true);return}const ids=[...state.selectedCatalogIds];if(ids.length>20){toast('单次最多检测 20 个商品',true);return}const button=$('#runSupplierMonitorBtn');button.disabled=true;button.textContent='正在创建任务…';try{state.supplierMonitorJob=await api('/api/supplier-monitor',{method:'POST',body:JSON.stringify({pipeline_ids:ids,confirm_external_requests:true})});renderSupplierMonitorJob(state.supplierMonitorJob);toast('供应商检测已进入后台队列');pollSupplierMonitor(state.supplierMonitorJob.job_id)}catch(error){button.disabled=false;button.textContent='检测选中商品';toast(error.message,true)}}
function supplierScheduleIds(){return $('#supplierScheduleProducts').value.split(/[\s,;]+/).map(value=>value.trim()).filter(Boolean)}
async function saveSupplierSchedule(){const enabled=$('#supplierScheduleEnabled').checked;if(enabled&&!$('#supplierScheduleConfirm').checked){toast('请确认周期性 AlphaShop 接口费用',true);return}try{const result=await api('/api/supplier-monitor/schedule',{method:'POST',body:JSON.stringify({enabled,interval_hours:Number($('#supplierScheduleInterval').value),pipeline_ids:supplierScheduleIds(),confirm_recurring_charges:$('#supplierScheduleConfirm').checked})});renderSupplierSchedule(result.schedule||{});toast(enabled?'定时检测计划已启用':'定时检测计划已暂停')}catch(error){toast(error.message,true)}}
async function deleteSupplierSchedule(){if(!confirm('确认删除定时供应商检测计划？已有监控历史不会删除。'))return;try{await api('/api/supplier-monitor/schedule',{method:'DELETE'});renderSupplierSchedule({enabled:false,pipeline_ids:[],interval_hours:24});toast('定时检测计划已删除')}catch(error){toast(error.message,true)}}
const baseRenderCatalogWithVersions=renderCatalog;
renderCatalog=function(){baseRenderCatalogWithVersions();document.querySelectorAll('[data-catalog-pipeline]').forEach(button=>{const pipelineId=button.dataset.catalogPipeline;const row=button.closest('td');if(!row||row.querySelector('[data-product-versions]'))return;const item=(state.productCatalog.products||[]).find(product=>String(product.pipeline_id)===String(pipelineId));const versionButton=document.createElement('button');versionButton.type='button';versionButton.dataset.productVersions=pipelineId;versionButton.textContent=`版本 ${Number(item?.product_version_count||0)}`;versionButton.onclick=()=>openProductVersions(pipelineId);row.classList.add('catalog-row-actions');row.appendChild(versionButton)})};
const baseRenderCatalogWithDelete=renderCatalog;
renderCatalog=function(){baseRenderCatalogWithDelete();document.querySelectorAll('[data-catalog-pipeline]').forEach(button=>{const cell=button.closest('td');if(!cell||cell.querySelector('[data-delete-catalog]'))return;const deleteButton=document.createElement('button');deleteButton.type='button';deleteButton.className='row-delete';deleteButton.dataset.deleteCatalog=button.dataset.catalogPipeline;deleteButton.textContent='删除';deleteButton.onclick=()=>deletePipelines([button.dataset.catalogPipeline]);cell.appendChild(deleteButton)})};
function openBatchEdit(){if(!state.selectedCatalogIds.size){toast('请先选择至少一个商品',true);return}$('#batchEditStore').innerHTML=storeOptions();$('#batchEditNote').textContent=`已选择 ${state.selectedCatalogIds.size} 个商品。仅修改明确勾选的字段；不会自动组装或上架。`;['#applyBatchStore','#applyBatchRate','#applyBatchDims','#applyBatchVat'].forEach(selector=>$(selector).checked=false);$('#batchEditResults').innerHTML='';$('#submitBatchEditBtn').disabled=false;$('#batchEditDialog').showModal()}
async function saveBatchEdit(event){event.preventDefault();try{const patch={};if($('#applyBatchStore').checked)patch.store_id=$('#batchEditStore').value;if($('#applyBatchRate').checked)patch.cny_to_rub_rate=$('#batchEditRate').value.trim();if($('#applyBatchVat').checked)patch.vat=$('#batchEditVat').value;if($('#applyBatchDims').checked){const dims=$('#batchEditDims').value.split('/').map(value=>Number(value.trim()));if(dims.length!==4||dims.some(value=>!Number.isInteger(value)||value<=0))throw new Error('默认尺寸必须是四个正整数');patch.dimension_defaults={depth:dims[0],width:dims[1],height:dims[2],weight:dims[3],dimension_unit:'mm',weight_unit:'g'}}if(!Object.keys(patch).length)throw new Error('请至少勾选一个要修改的字段');$('#submitBatchEditBtn').disabled=true;const result=await api('/api/products/batch-edit',{method:'POST',body:JSON.stringify({pipeline_ids:[...state.selectedCatalogIds],patch,note:$('#batchEditDescription').value.trim()})});$('#batchEditResults').innerHTML=(result.results||[]).map(item=>`<div class="batch-result ${item.status==='FAIL'?'fail':'pass'}"><i></i><span><b>${escapeHtml(item.pipeline_id)} · ${escapeHtml(item.status==='UPDATED'?'已保存新版本':item.status==='UNCHANGED'?'没有变化':'失败')}</b><small>${escapeHtml(item.error||item.version_id||'')}</small></span></div>`).join('');state.selectedCatalogIds.clear();await load();await loadCatalog();toast(`批量编辑完成：更新 ${result.updated}，未变化 ${result.unchanged}，失败 ${result.failed}`,result.failed>0)}catch(error){toast(error.message,true)}finally{$('#submitBatchEditBtn').disabled=false}}
function settingsSummary(settings){const dims=settings?.dimension_defaults||{};const size=[dims.depth,dims.width,dims.height,dims.weight].every(value=>value!==null&&value!==undefined)?`${dims.depth}/${dims.width}/${dims.height}/${dims.weight}${dims.weight_unit||'g'}`:'未设置';const vat=Number(settings?.vat||0)*100;return`店铺 ${settings?.store_id||'未设置'} · 汇率 ${settings?.cny_to_rub_rate||'未设置'} · 尺寸重量 ${size} · VAT ${vat}%`}
async function openProductVersions(pipelineId){try{state.versionPipelineId=pipelineId;const history=await api(`/api/pipelines/${encodeURIComponent(pipelineId)}/versions`);$('#productVersionsTitle').textContent=`商品 ${pipelineId} · 版本历史`;const versions=history.versions||[];$('#productVersionsList').innerHTML=versions.length?versions.map((item,index)=>`<article class="version-item"><div><b>${index===0?'当前/最新 · ':''}${escapeHtml(item.note||item.source)}</b><small>${escapeHtml(formatDate(item.created_at))} · ${escapeHtml(item.actor||'system')} · ${escapeHtml(settingsSummary(item.settings))}</small></div><button type="button" data-restore-version="${escapeHtml(item.version_id)}" ${index===0?'disabled':''}>回滚到此版本</button></article>`).join(''):'<div class="store-empty">尚无版本记录。首次批量编辑后会保留初始版本和新版本。</div>';document.querySelectorAll('[data-restore-version]').forEach(button=>button.onclick=()=>restoreProductVersion(button.dataset.restoreVersion));$('#productVersionsDialog').showModal()}catch(error){toast(error.message,true)}}
async function restoreProductVersion(versionId){if(!confirm('确认回滚到该版本？第四、第五阶段将标记为需要更新，但不会自动提交。'))return;try{await api(`/api/pipelines/${encodeURIComponent(state.versionPipelineId)}/versions/${encodeURIComponent(versionId)}/restore`,{method:'POST',body:'{}'});await load();await loadCatalog();await openProductVersions(state.versionPipelineId);toast('版本已回滚，请重新运行第四阶段生成 Payload')}catch(error){toast(error.message,true)}}
function formatBytes(value){const bytes=Number(value||0);if(bytes<1024)return`${bytes} B`;if(bytes<1024*1024)return`${(bytes/1024).toFixed(1)} KB`;if(bytes<1024*1024*1024)return`${(bytes/1024/1024).toFixed(1)} MB`;return`${(bytes/1024/1024/1024).toFixed(2)} GB`}
function assetTypeName(value){return{translated:'俄语翻译图',ai_generated:'AI 优化图'}[value]||value||'图片'}
function filteredAssets(){const query=state.assetSearch.toLowerCase();return(state.assetLibrary.assets||[]).filter(item=>{if(state.assetTypeFilter!=='all'&&item.asset_type!==state.assetTypeFilter)return false;if(state.assetStatusFilter==='managed'&&!item.managed)return false;if(state.assetStatusFilter==='external'&&item.managed)return false;if(state.assetStatusFilter==='orphaned'&&!item.orphaned)return false;if(state.assetStatusFilter==='published'&&!item.published)return false;if(!query)return true;return`${item.display_name||''} ${JSON.stringify(item.references||[])}`.toLowerCase().includes(query)})}
function renderAssets(){const summary=state.assetLibrary.summary||{};$('#assetMetrics').innerHTML=[['已处理图片',summary.total||0,'仅 AI 优化与俄语翻译'],['OSS 托管',summary.managed||0,formatBytes(summary.managed_bytes)],['可安全清理',summary.orphaned||0,formatBytes(summary.orphaned_bytes)],['已上架保护',summary.published||0,'永不自动删除']].map(([label,value,hint])=>`<article><span>${label}</span><strong>${value}</strong><small>${hint}</small></article>`).join('');const rows=filteredAssets();$('#assetEmpty').classList.toggle('hidden',rows.length>0);$('#assetGrid').innerHTML=rows.map(item=>{const refs=item.references||[];const badges=[`<span class="asset-badge managed">${escapeHtml(item.image_label||assetTypeName(item.asset_type))}</span>`,item.managed?'<span class="asset-badge external">OSS</span>':'<span class="asset-badge external">外部链接</span>',item.orphaned?'<span class="asset-badge orphaned">可清理</span>':'',item.published?'<span class="asset-badge protected">已上架保护</span>':''].join('');const refButtons=refs.slice(0,3).map(ref=>`<button type="button" data-asset-pipeline="${escapeHtml(ref.pipeline_id)}">打开商品${ref.sku_id?` · SKU ${escapeHtml(ref.sku_id)}`:''}</button>`).join('');const title=item.product_title||refs[0]?.title_zh||item.display_name||'历史图片资产';const selector=item.can_delete&&hasPermission('storage.manage')?`<input class="asset-select" type="checkbox" data-asset-select="${escapeHtml(item.asset_id)}" ${state.selectedAssetIds.has(String(item.asset_id))?'checked':''} aria-label="选择 ${escapeHtml(title)}">`:'<span class="asset-select-placeholder"></span>';return`<article class="asset-card asset-link-card">${selector}<div class="asset-link-icon">↗</div><div class="asset-body"><div class="asset-badges">${badges}</div><a class="asset-file-link" href="/api/assets/${encodeURIComponent(item.asset_id)}/preview" target="_blank" rel="noopener noreferrer" title="点击查看图片">${escapeHtml(title)}</a><div class="asset-meta"><span>点击商品标题查看图片</span><span>${item.size_bytes?formatBytes(item.size_bytes):'链接图片'}</span><span>${refs.length} 个商品引用</span></div><div class="asset-refs">${refButtons||'<span>当前无商品引用</span>'}${refs.length>3?`<span>+${refs.length-3}</span>`:''}</div>${item.can_delete&&hasPermission('storage.manage')?`<button type="button" class="asset-delete" data-delete-asset="${escapeHtml(item.asset_id)}">从 OSS 永久删除</button>`:''}</div></article>`}).join('');document.querySelectorAll('[data-asset-pipeline]').forEach(button=>button.onclick=async()=>{await selectPipeline(button.dataset.assetPipeline);showWorkspace('products')});document.querySelectorAll('[data-delete-asset]').forEach(button=>button.onclick=()=>deleteAsset(button.dataset.deleteAsset));document.querySelectorAll('[data-asset-select]').forEach(control=>control.onchange=()=>{const id=String(control.dataset.assetSelect);control.checked?state.selectedAssetIds.add(id):state.selectedAssetIds.delete(id);updateAssetSelection(rows)});updateAssetSelection(rows)}
function updateAssetSelection(rows=filteredAssets()){const safe=rows.filter(item=>item.can_delete);const selected=state.selectedAssetIds.size;$('#deleteSelectedAssetsBtn').textContent=`删除（${selected}）`;$('#deleteSelectedAssetsBtn').disabled=!selected||!hasPermission('storage.manage');const all=safe.length>0&&safe.every(item=>state.selectedAssetIds.has(String(item.asset_id)));$('#assetSelectAll').checked=all;$('#assetSelectAll').indeterminate=!all&&safe.some(item=>state.selectedAssetIds.has(String(item.asset_id)))}
async function deleteAssets(ids){const unique=[...new Set(ids.map(String))];if(!unique.length)return;if(!confirm(`确认从 OSS 永久删除选中的 ${unique.length} 张无引用图片？此操作无法恢复。`))return;try{const result=await api('/api/assets/batch-delete',{method:'POST',body:JSON.stringify({asset_ids:unique,confirm_delete:true})});state.assetLibrary={schema_version:result.schema_version,summary:result.summary,assets:result.assets,generated_at:result.generated_at};const removed=new Set(result.deleted||[]);state.selectedAssetIds=new Set([...state.selectedAssetIds].filter(id=>!removed.has(id)));renderAssets();toast(`已删除 ${removed.size} 张图片${result.blocked?.length?`，${result.blocked.length} 张受保护`:''}`,Boolean(result.blocked?.length))}catch(error){toast(error.message,true)}}
async function loadAssets(){try{state.assetLibrary=await api('/api/assets');renderAssets()}catch(error){toast(error.message,true)}}
async function deleteAsset(identifier){if(!confirm('确认从 OSS 永久删除该无引用图片？此操作无法恢复。'))return;try{state.assetLibrary=await api(`/api/assets/${encodeURIComponent(identifier)}`,{method:'DELETE'});renderAssets();toast('无引用图片已从 OSS 删除')}catch(error){toast(error.message,true)}}
async function loadNotifications(showError=true){try{state.notifications=await api('/api/notifications');renderNotifications()}catch(error){if(showError)toast(error.message,true)}}
async function markNotificationsRead(){try{state.notifications=await api('/api/notifications/read',{method:'POST',body:JSON.stringify({all:true})});renderNotifications();toast('通知已全部标记为已读')}catch(error){toast(error.message,true)}}
function showWorkspace(view){const operations=view==='operations';const pricing=view==='pricing';const tasks=view==='tasks';const catalog=view==='catalog';const research=view==='research';const assets=view==='assets';$('#productShell').classList.toggle('hidden',operations||pricing||tasks||catalog||research||assets);$('#operationsView').classList.toggle('hidden',!operations);$('#pricingView').classList.toggle('hidden',!pricing);$('#taskView').classList.toggle('hidden',!tasks);$('#catalogView').classList.toggle('hidden',!catalog);$('#researchView').classList.toggle('hidden',!research);$('#assetView').classList.toggle('hidden',!assets);$('#productNav').classList.toggle('active',view==='products');$('#catalogNav').classList.toggle('active',catalog);$('#researchNav').classList.toggle('active',research);$('#taskNav').classList.toggle('active',tasks);$('#assetNav').classList.toggle('active',assets);$('#operationsNav').classList.toggle('active',operations);$('#pricingNav').classList.toggle('active',pricing);if(operations){$('#operationsStore').innerHTML=operationsStoreOptions();$('#refreshOperationsBtn').disabled=!state.stores.length;$('#financeSettingsBtn').disabled=!state.stores.length||!hasPermission('finance.read');if(!state.stores.length)$('#operationsEmpty').textContent='请先回到商品工作台授权 Ozon 店铺。'}if(pricing){$('#pricingStore').innerHTML=operationsStoreOptions();$('#loadPricingSettingsBtn').disabled=!state.stores.length||!hasPermission('finance.read')}if(tasks)loadTaskCenter();if(catalog)loadCatalog();if(research)loadResearch();if(assets)loadAssets()}
function applyAccessNavigation(){const workspace=hasPermission('workspace.read');['productNav','catalogNav','researchNav','taskNav','assetNav','operationsNav'].forEach(id=>{$(`#${id}`).classList.toggle('hidden',!workspace)});$('#pricingNav').classList.toggle('hidden',!(hasPermission('pricing.use')||hasPermission('finance.read')));$('#pricingNav').disabled=!(hasPermission('pricing.use')||hasPermission('finance.read'));$('#storesNav').classList.toggle('hidden',!hasPermission('stores.manage'));$('#storesNav').disabled=!hasPermission('stores.manage');$('#aiProviderBtn').classList.toggle('hidden',!hasPermission('ai.manage'));$('#objectStorageBtn').classList.toggle('hidden',!hasPermission('storage.manage'));$('#notificationBtn').classList.toggle('hidden',!workspace);const teamSection=document.querySelector('.team-section');if(teamSection)teamSection.classList.toggle('hidden',!hasPermission('team.manage'))}
function renderAccount(){if(!state.account)return;const account=state.account;const name=account.identity.display_name||account.identity.username;const initial=name.slice(0,1).toUpperCase();$('#accountAvatar').textContent=initial;$('#accountDialogAvatar').textContent=initial;$('#accountName').textContent=name;$('#accountDialogName').textContent=name;$('#accountPlan').textContent=account.plan.name;$('#accountRole').textContent=`${account.identity.role_name} · ${account.workspace.name}`;$('#planName').textContent=account.plan.name;$('#planPrice').textContent=`¥${Number(account.plan.monthly_price_cny).toLocaleString('zh-CN')} / 月`;$('#billingPeriod').textContent=`计费周期 ${account.period}`;$('#usageGrid').innerHTML=Object.entries(account.plan.limits).map(([key,limit])=>{const used=Number(account.usage[key]||0);if(limit===null||limit===undefined)return `<article><div><span>${usageLabel(key)}</span><b>${used} / 不限</b></div><progress class="usage-track" max="100" value="0" aria-label="${escapeHtml(usageLabel(key))}不限"></progress><small>授权数量不限，单次上架仅选择一个店铺</small></article>`;const percent=Math.min(100,Math.round(used/Math.max(1,Number(limit))*100));return `<article><div><span>${usageLabel(key)}</span><b>${used} / ${limit}</b></div><progress class="usage-track" max="100" value="${percent}" aria-label="${escapeHtml(usageLabel(key))}用量 ${percent}%"></progress><small>${percent}% 已使用</small></article>`}).join('');$('#permissionList').innerHTML=(account.identity.permission_labels||[]).map(item=>`<span>✓ ${escapeHtml(item)}</span>`).join('');$('#createForm').querySelector('button[type="submit"]').disabled=!hasPermission('pipeline.create');applyAccessNavigation();renderTeam()}
async function load(){try{const account=await api('/api/account');state.account=account;const workspace=hasPermission('workspace.read');const [list,config,stores,provider,dashboard,team,registrations]=workspace?await Promise.all([api('/api/pipelines'),api('/api/config-status'),api('/api/stores'),api('/api/ai-provider'),api('/api/dashboard'),api('/api/team'),hasPermission('team.manage')?api('/api/registrations'):Promise.resolve({accounts:[],total:0})]):await Promise.all([Promise.resolve({pipelines:[]}),Promise.resolve({dry_run:true}),hasPermission('stores.manage')?api('/api/stores'):Promise.resolve({stores:[]}),Promise.resolve({provider:{}}),Promise.resolve({counters:{},issues:[]}),Promise.resolve({members:[],roles:{}}),Promise.resolve({accounts:[],total:0})]);state.pipelines=list.pipelines;state.config=config;state.stores=stores.stores;state.aiProvider=provider.provider;state.dashboard=dashboard;state.team=team;state.registrations=registrations;$('#modeBadge').textContent=config.dry_run?'DRY RUN':'LIVE MODE';$('#modeBadge').className=`badge ${config.dry_run?'safe':'live'}`;$('#aiProviderState').textContent=state.aiProvider.text_api_key_configured&&state.aiProvider.image_api_key_configured?'✓':'0';$('#operationsStore').innerHTML=operationsStoreOptions();$('#pricingStore').innerHTML=operationsStoreOptions();if(workspace&&state.current){const found=state.pipelines.find(p=>p.pipeline_id===state.current.pipeline_id);if(found)state.current=await api(`/api/pipelines/${encodeURIComponent(found.pipeline_id)}`)}if(!workspace)state.current=null;renderAccount();renderStores();renderList();renderDetail();if(!workspace&&hasPermission('pricing.use'))showWorkspace('pricing')}catch(error){toast(error.message,true)}}
async function setRegistrationAuthorization(username,action){const verb=action==='authorize'?'授权':'解除授权';if(!confirm(`确认${verb}该注册账号？${action==='revoke'?'该用户会立即退出登录，重新授权前无法使用系统。':''}`))return;try{await api(`/api/registrations/${encodeURIComponent(username)}/${action}`,{method:'POST',body:'{}'});await load();toast(`账号已${verb}`)}catch(error){toast(error.message,true)}}
async function deleteRegistration(username){if(!confirm('确认永久删除该注册账号？\n\n账号、全部登录会话及其绑定的 Ozon 店铺凭证都会删除，此操作无法恢复。'))return;try{const result=await api(`/api/registrations/${encodeURIComponent(username)}`,{method:'DELETE'});await load();toast(`注册账号已删除${result.removed_store_ids?.length?`，同时清理 ${result.removed_store_ids.length} 个店铺凭证`:''}`)}catch(error){toast(error.message,true)}}
async function saveTeamMember(event){event.preventDefault();try{await api('/api/team',{method:'POST',body:JSON.stringify({username:$('#memberUsername').value.trim(),display_name:$('#memberDisplayName').value.trim(),role:$('#memberRole').value})});$('#memberUsername').value='';$('#memberDisplayName').value='';await load();toast('团队成员已保存，请在服务器创建同名登录凭证')}catch(error){toast(error.message,true)}}
async function deleteTeamMember(username){if(!confirm(`确认移除团队成员 ${username}？`))return;try{await api(`/api/team/${encodeURIComponent(username)}`,{method:'DELETE'});await load();toast('团队成员已移除')}catch(error){toast(error.message,true)}}
async function selectPipeline(id){try{state.current=await api(`/api/pipelines/${encodeURIComponent(id)}`);renderList();renderDetail()}catch(error){toast(error.message,true)}}
async function viewArtifact(n){try{const value=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/artifacts/${n}`);const failures=state.current?.stages?.[String(n)]?.failures||[];$('#artifactTitle').textContent=`0${n} · ${state.current.artifacts[String(n)]}`;$('#console').textContent=`${failures.length?`门禁失败：\n- ${failures.join('\n- ')}\n\n`:''}${JSON.stringify(value,null,2)}`;if(n===3){state.imageReview=value;renderGeneratedImageReview();$('#imageReviewDialog').showModal()}}catch(error){toast(error.message,true)}}
function field(label,name,value=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" value="${escapeHtml(value)}"></div>`}
function storeField(lockToPipeline=false){const assigned=state.current?.store_id||'';const locked=lockToPipeline&&assigned;const selected=assigned||(state.stores.length===1?state.stores[0].store_id:'');const placeholder=!selected&&state.stores.length>1?'<option value="" selected disabled>请选择本次上架的唯一店铺</option>':'';return `<div class="field"><label for="stageStore">本次上架的 OZON 店铺</label><select id="stageStore" required ${locked?'disabled':''}>${placeholder}${storeOptions(selected,Boolean(locked))}</select><small>${locked?'已锁定为当前流水线的唯一目标店铺；如需更换，请返回第二阶段重新选择并映射类目。':'每次上架只能选择一家店铺；已授权店铺数量不受限制。'}</small></div>`}
function categoryOptionLabel(option){const zhPath=(option.category_path_zh||[]).join(' / ');const zhType=option.type_name_zh||'';const ruPath=(option.category_path_ru||[]).join(' / ');const ruType=option.type_name_ru||'';return `${zhPath}${zhType?` · ${zhType}`:''}${ruPath?` ｜ ${ruPath}`:''}${ruType?` · ${ruType}`:''} ｜ category ${option.ozon_category_id} / type ${option.ozon_type_id}`}
async function searchOzonCategories(){const query=$('#categoryQuery').value.trim();if(query.length<2){toast('请输入至少 2 个准确的中文或俄文类目关键词',true);return}const button=$('#searchCategoryBtn');const select=$('#manualCategory');button.disabled=true;button.textContent='正在搜索…';select.innerHTML='<option value="">正在搜索官方类目…</option>';try{const storeId=$('#stageStore').value;const result=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/category-options?q=${encodeURIComponent(query)}&store_id=${encodeURIComponent(storeId)}`);const options=result.options||[];select.innerHTML='<option value="">请选择正确的 Ozon 官方类目 / 商品类型</option>'+options.map(option=>`<option value="${option.ozon_category_id}:${option.ozon_type_id}">${escapeHtml(categoryOptionLabel(option))}</option>`).join('');$('#categorySearchStatus').textContent=options.length?`找到 ${result.total_matches} 个匹配项，显示前 ${options.length} 个。选择后会直接复用本次官方搜索结果，不再重复扫描类目树。`:'没有匹配项，请换用更简短、准确的商品品名搜索。'}catch(error){select.innerHTML='<option value="">读取失败，请重试</option>';$('#categorySearchStatus').textContent=error.message;toast(error.message,true)}finally{button.disabled=false;button.textContent='搜索 Ozon 官方类目'}}
function attributeTextValue(value){if(Array.isArray(value))return value.join(', ');if(value&&typeof value==='object')return JSON.stringify(value);return String(value??'')}
function requiredAttributeFields(attributes){if(!attributes.length)return '<div class="warning">Ozon 当前类目没有可编辑特征。</div>';return `<div class="warning">以下是当前类目的全部 Ozon 特征（包含选填项）。字段名和字典候选值使用 Ozon 官方简体中文显示；系统内部保留同一个属性 ID，组装上架载荷时自动换成 Ozon 俄语合法值。自由文本可直接输入中文，保存第四阶段时会调用已配置的 AI 文本服务一次性译为俄语。</div>${attributes.map(attribute=>{const id=attribute.attribute_id;const required=attribute.is_required;const zhName=attribute.attribute_name_zh||`Ozon 特征 ${id}`;const ruName=attribute.attribute_name_ru||'';const label=`${required?'【必填】':'【可选】'} ${zhName} · ID ${id}`;const ruHint=ruName&&ruName!==zhName?`Ozon 俄语字段：${escapeHtml(ruName)}`:'';if(attribute.is_dictionary){const selectedId=attribute.selected_dictionary_value_id??'';const current=selectedId!==''?`<option value="${selectedId}" selected>已选择 · ID ${selectedId}</option>`:'';return `<div class="field"><label for="attribute_${id}">${escapeHtml(label)}</label><select id="attribute_${id}" data-required-attribute="${id}" data-attribute-kind="dictionary" data-is-required="${required}" data-original="${selectedId}" data-override-required="${attribute.override_required}" data-values-loaded="false"><option value="">${required?'请选择 Ozon 合法值':'留空，不提交此可选特征'}</option>${current}</select><small>${ruHint}${ruHint?' · ':''}展开时从 Ozon API 实时加载中文候选值</small></div>`}const textValue=attributeTextValue(attribute.selected_value);return `<div class="field"><label for="attribute_${id}">${escapeHtml(label)}</label><input id="attribute_${id}" data-required-attribute="${id}" data-attribute-kind="text" data-is-required="${required}" data-original="${escapeHtml(textValue)}" data-override-required="${attribute.override_required}" value="${escapeHtml(textValue)}" placeholder="${required?'请输入准确的中文特征值':'可选，可输入中文，留空则不提交'}"><small>${ruHint}${ruHint?' · ':''}新输入的中文会在载荷组装前译为俄语；已有俄语值保持不变</small></div>`}).join('')}`}
async function loadAttributeDictionary(control){if(control.dataset.valuesLoaded==='true')return;control.dataset.valuesLoaded='loading';const current=control.value;const empty=control.options[0]?.textContent||'留空';try{const result=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/attributes/${encodeURIComponent(control.dataset.requiredAttribute)}/values`);control.innerHTML=`<option value="">${escapeHtml(empty)}</option>`+(result.options||[]).map(option=>`<option value="${option.dictionary_value_id}" ${String(option.dictionary_value_id)===current?'selected':''}>${escapeHtml(option.value)} · ${option.dictionary_value_id}</option>`).join('');control.dataset.valuesLoaded='true'}catch(error){control.dataset.valuesLoaded='false';toast(error.message,true)}}
async function openStage(n){state.dialogStage=n;const titles=['','采集 1688 商品','匹配 OZON 类目','生成俄语内容','组装上传 Payload','提交与追踪'];$('#dialogTitle').textContent=titles[n];let html='';if(n===1)html='<div class="warning">重新采集会调用遨虾实时详情接口，并使后续产物需要重新验证。</div>';if(n===2)html=storeField()+field('自动选择置信度阈值','threshold','0.70');if(n===3){const aiReady=state.aiProvider?.text_api_key_configured&&state.aiProvider?.image_api_key_configured;html=`<div class="warning">系统以采集图为真实性依据，生成统一视觉的 1 张主图和 7 张详情图：主图、参数、促销引导、设计对比、人物使用、核心卖点、2–3 个使用场景、品质细节。全部为 3:4 竖版俄语图片。</div><div class="field"><label for="mediaMode">图片处理方式</label><select id="mediaMode"><option value="image_plan" ${aiReady?'selected':''} ${aiReady?'':'disabled'}>生成 8 张独立 AI 商品图（必选）</option></select></div><div class="field"><label for="textMode">俄语文本方式</label><select id="textMode"><option value="ai_generate" ${aiReady?'selected':''} ${aiReady?'':'disabled'}>新版 OZON 运营文案与 SKU 标题</option></select></div><div class="field"><label><input id="watermarkEnabled" type="checkbox"> 为 AI 生成图片添加水印</label><small>默认关闭。Ozon 部分类目或主图可能限制水印，请确认平台规则后启用；启用时必须已配置 OSS。</small></div><div id="watermarkFields" class="hidden"><div class="field-grid"><div class="field"><label for="watermarkType">水印类型</label><select id="watermarkType"><option value="text">文字水印</option><option value="image">图片水印</option></select></div><div class="field"><label for="watermarkPosition">位置</label><select id="watermarkPosition"><option value="top_left">左上</option><option value="top_center">上方居中</option><option value="top_right">右上</option><option value="center_left">左侧居中</option><option value="center">正中</option><option value="center_right">右侧居中</option><option value="bottom_left">左下</option><option value="bottom_center">下方居中</option><option value="bottom_right" selected>右下</option></select></div></div><div id="watermarkTextField" class="field"><label for="watermarkText">文字内容</label><input id="watermarkText" maxlength="80" placeholder="例如：Northstar"><input id="watermarkColor" type="color" value="#ffffff" title="文字颜色"></div><div id="watermarkImageField" class="field hidden"><label for="watermarkImageUrl">图片水印 HTTPS 地址</label><input id="watermarkImageUrl" type="url" placeholder="https://.../logo.png"><small>建议使用透明背景 PNG，可先上传到已配置的 OSS。</small></div><div class="field-grid"><div class="field"><label for="watermarkSize">大小（占图片宽度 %）</label><input id="watermarkSize" type="number" min="5" max="40" value="18"></div><div class="field"><label for="watermarkOpacity">透明度（%）</label><input id="watermarkOpacity" type="number" min="5" max="100" value="35"></div></div></div>${aiReady?'':`<div class="warning danger">AI 服务尚未配置完整，请先点击页面顶部“AI 服务”。</div>`}`};if(n===4){html=storeField()+field('CNY → 店铺币种汇率','rate','12.50')+field('估算尺寸：深 / 宽 / 高 / 重量(g)','dims','80 / 80 / 200 / 350')+'<div class="warning">原产国默认匹配中国；颜色、材质、香型、数量、尺寸等特征会依据采集事实自动填写并翻译。没有可靠依据的字段仍需人工确认。</div><div id="requiredAttributes"><div class="warning">正在读取当前类目的全部 Ozon 特征…</div></div>'}if(n===5){const blocked=state.config?.dry_run;html=`<div class="warning danger">${blocked?'服务器当前为 DRY RUN，真实提交已锁定；本次运行绝不会被标记为上架成功。请先在服务器启用 LIVE MODE。':'服务器已处于 LIVE MODE。勾选确认后才会调用 Ozon，并且只有取得 task_id、导入成功且属性回查通过才会显示 PASS。'}</div><div class="field"><label><input id="execute" type="checkbox" ${blocked?'disabled':''}> 我明确要求执行真实提交</label></div>`}$('#dialogFields').innerHTML=html;$('#stageDialog').showModal();if(n===3){const refreshWatermark=()=>{const enabled=$('#watermarkEnabled').checked;$('#watermarkFields').classList.toggle('hidden',!enabled);const image=$('#watermarkType').value==='image';$('#watermarkTextField').classList.toggle('hidden',image);$('#watermarkImageField').classList.toggle('hidden',!image)};$('#watermarkEnabled').onchange=refreshWatermark;$('#watermarkType').onchange=refreshWatermark;refreshWatermark()}if(n===4){try{const result=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/required-attributes`);$('#requiredAttributes').innerHTML=requiredAttributeFields(result.attributes||[]);document.querySelectorAll('[data-attribute-kind="dictionary"]').forEach(control=>control.onfocus=()=>loadAttributeDictionary(control))}catch(error){$('#requiredAttributes').innerHTML=`<div class="warning danger">${escapeHtml(error.message)}</div>`;toast(error.message,true)}}}
const delay=milliseconds=>new Promise(resolve=>setTimeout(resolve,milliseconds));
async function waitForStage(n){for(let attempt=0;attempt<300;attempt++){await delay(3000);state.current=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}`);renderList();renderDetail();const status=stageStatus(state.current,n);$('#console').textContent=`阶段 ${n} 正在后台执行… 已等待 ${Math.round((attempt+1)*3)} 秒${n===5?'；Ozon 正在处理商品、图片和属性回查，请勿重复提交':''}`;if(status!=='RUNNING')return status}throw new Error(`阶段 ${n} 后台执行超过 15 分钟，任务已超出正常时限，请刷新查看失败诊断`)}
async function runStage(event){event.preventDefault();const n=state.dialogStage;let body={};try{if(n===2){body.confidence_threshold=Number($('#threshold').value);body.store_id=$('#stageStore').value}if(n===3){body.media_mode=$('#mediaMode').value;body.text_mode=$('#textMode').value;const enabled=$('#watermarkEnabled').checked;body.watermark_settings={enabled,type:$('#watermarkType').value,text:$('#watermarkText').value.trim(),image_url:$('#watermarkImageUrl').value.trim(),color:$('#watermarkColor').value,size_percent:Number($('#watermarkSize').value),opacity_percent:Number($('#watermarkOpacity').value),position:$('#watermarkPosition').value}}if(n===4){const dims=$('#dims').value.split('/').map(v=>Number(v.trim()));if(dims.length!==4||dims.some(v=>!Number.isFinite(v)||v<=0))throw new Error('尺寸必须是四个正数');const attributeOverrides={};document.querySelectorAll('[data-required-attribute]').forEach(control=>{const value=control.value.trim();if(!value&&control.dataset.isRequired==='true')throw new Error(`请填写或选择 ${control.previousElementSibling?.textContent||'Ozon 必填属性'}`);const changed=value!==String(control.dataset.original??'');if(value&&(changed||control.dataset.overrideRequired==='true'))attributeOverrides[control.dataset.requiredAttribute]=control.dataset.attributeKind==='dictionary'?{dictionary_value_id:Number(value)}:{value}});body.store_config={store_id:$('#stageStore').value,cny_to_rub_rate:$('#rate').value.trim(),dimension_defaults:{depth:dims[0],width:dims[1],height:dims[2],weight:dims[3],dimension_unit:'mm',weight_unit:'g'},vat:'0',attribute_overrides:attributeOverrides}}if(n===5){if(state.config?.dry_run)throw new Error('服务器仍为 DRY RUN，请先启用 LIVE MODE 并重启服务');if(!$('#execute').checked)throw new Error('请勾选“我明确要求执行真实提交”');body.execute=true}$('#stageDialog').close();$('#console').textContent=`正在执行阶段 ${n}…`;let result=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/stages/${n}`,{method:'POST',body:JSON.stringify(body)});if(result.status==='RUNNING'){toast(`阶段 ${n} 已转入后台执行`);await selectPipeline(state.current.pipeline_id);await waitForStage(n);result={...result,status:stageStatus(state.current,n),failures:state.current.stages?.[String(n)]?.failures||[]}}const failures=result.failures||[];const details=failures.join('；');if(failures.length)$('#console').textContent=`门禁失败：\n- ${failures.join('\n- ')}`;toast(`阶段 ${n}：${result.status}${details?` · ${details}`:''}`,result.status==='FAIL');await selectPipeline(state.current.pipeline_id);if(state.current.artifacts?.[String(n)])await viewArtifact(n)}catch(error){toast(error.message,true)}}
