function skuPriceEditor(source){const excluded=new Set((state.current?.product_settings?.excluded_sku_ids||[]).map(String));const rows=(source.sku_list||[]).filter(item=>item&&item.sku_id!=null&&!excluded.has(String(item.sku_id)));if(!rows.length)return '<div class="warning danger">没有可上架的 SKU，请先在第一阶段的“管理 SKU”中恢复至少一个 SKU。</div>';return `<div class="warning">这里只显示保留的 SKU。第四阶段先按采购成本和店铺定价参数计算实际售价，提交到 Ozon 的上架价格固定为该实际售价的 2 倍；系统绝不会使用 0 元上架。</div>${rows.map(item=>{const id=String(item.sku_id);const specs=item.specification_text_zh||((item.specification_zh||[]).map(part=>`${part.name||''}:${part.value||''}`).join('；'))||'默认规格';const price=item.purchase_price_cny??'';return `<div class="field"><label for="sku_price_${escapeHtml(id)}">SKU ${escapeHtml(id)} · ${escapeHtml(specs)} · 人民币采购成本</label><input id="sku_price_${escapeHtml(id)}" type="number" min="0.01" step="0.01" data-sku-price="${escapeHtml(id)}" value="${escapeHtml(price)}" placeholder="请输入真实采购成本，例如 12.80"></div>`}).join('')}`}
async function openStageWithPriceEditor(n){await baseOpenStageWithCategoryPicker(n);if(n!==4)return;try{const selected=state.stores.find(store=>store.store_id===$('#stageStore').value);if(selected?.currency_code==='CNY'){$('#rate').value='1.00';$('#rate').readOnly=true;$('#rate').previousElementSibling.textContent='CNY 店铺：建议售价直接以人民币提交'}else if(selected&&hasPermission('finance.read')){const settings=(await api(`/api/finance-settings?store_id=${encodeURIComponent(selected.store_id)}`)).settings;$('#rate').value=settings.cny_to_rub_rate}const source=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/artifacts/1`);const target=$('#requiredAttributes');target.insertAdjacentHTML('beforebegin',`<div id="skuPriceEditor">${skuPriceEditor(source)}</div>`)}catch(error){toast(`读取 SKU 采购价或定价参数失败：${error.message}`,true)}}
async function runStageWithPriceEditor(event){if(state.dialogStage!==4)return baseRunStageWithCategoryPicker(event);event.preventDefault();try{const dims=$('#dims').value.split('/').map(value=>Number(value.trim()));if(dims.length!==4||dims.some(value=>!Number.isFinite(value)||value<=0))throw new Error('尺寸必须是四个正数');const skuPriceOverrides={};document.querySelectorAll('[data-sku-price]').forEach(control=>{const value=control.value.trim();if(!value)throw new Error(`请填写 SKU ${control.dataset.skuPrice} 的真实人民币采购价`);if(!Number.isFinite(Number(value))||Number(value)<=0)throw new Error(`SKU ${control.dataset.skuPrice} 的采购价必须大于 0`);skuPriceOverrides[control.dataset.skuPrice]=value});const attributeOverrides={};document.querySelectorAll('[data-required-attribute]').forEach(control=>{const value=control.value.trim();if(!value&&control.dataset.isRequired==='true')throw new Error(`请填写或选择 ${control.previousElementSibling?.textContent||'Ozon 必填属性'}`);const changed=value!==String(control.dataset.original??'');if(value&&(changed||control.dataset.overrideRequired==='true'))attributeOverrides[control.dataset.requiredAttribute]=control.dataset.attributeKind==='dictionary'?{dictionary_value_id:Number(value)}:{value}});const body={store_config:{store_id:$('#stageStore').value,cny_to_rub_rate:$('#rate').value.trim(),dimension_defaults:{depth:dims[0],width:dims[1],height:dims[2],weight:dims[3],dimension_unit:'mm',weight_unit:'g'},vat:$('#stageVat')?.value||'0',sku_price_overrides:skuPriceOverrides,attribute_overrides:attributeOverrides}};$('#stageDialog').close();$('#console').textContent='正在校验采购价并组装 Ozon Payload…';const result=await api(`/api/pipelines/${encodeURIComponent(state.current.pipeline_id)}/stages/4`,{method:'POST',body:JSON.stringify(body)});const failures=result.failures||[];if(failures.length)$('#console').textContent=`门禁失败：\n- ${failures.join('\n- ')}`;toast(`阶段 4：${result.status}${failures.length?` · ${failures.join('；')}`:''}`,result.status==='FAIL');await selectPipeline(state.current.pipeline_id);if(state.current.artifacts?.['4'])await viewArtifact(4)}catch(error){toast(error.message,true)}}
