function renderResearch(){const summary=state.marketResearch.summary||{};$('#researchMetrics').innerHTML=[['候选商品',summary.total||0,'自动去重'],['待审核',summary.new||0,'等待运营判断'],['已收藏 / 通过',`${summary.shortlisted||0} / ${summary.approved||0}`,'进入货源匹配'],['已找到货源',summary.sourced||0,'已创建上架任务']].map(([label,value,hint])=>`<article><span>${label}</span><strong>${escapeHtml(value)}</strong><small>${hint}</small></article>`).join('');setResearchRules(state.marketResearch.rules);const rows=filteredResearch();$('#researchTable').innerHTML=rows.length?rows.map(item=>{const metrics=[item.price_rub?`${item.price_rub}₽`:'价格未知',item.orders?`订购 ${item.orders}`:'订购量未知',item.revenue_rub?`销售额 ${item.revenue_rub}₽`:'',item.daily_sales?`日销 ${item.daily_sales}`:''].filter(Boolean).join(' · ');const competition=[item.sellers?`${item.sellers} 个卖家`:'卖家数未知',item.rating?`评分 ${item.rating}`:'',item.reviews?`${item.reviews} 评论`:''].filter(Boolean).join(' · ');const conversion=[item.card_views?`浏览 ${item.card_views}`:'',item.conversion_rate_percent?`转化 ${item.conversion_rate_percent}%`:'',item.ad_share_percent?`广告 ${item.ad_share_percent}%`:'',item.return_rate_percent?`退货 ${item.return_rate_percent}%`:''].filter(Boolean).join(' · ');return`<tr><td><div class="catalog-product"><div class="catalog-thumb">${item.image_url?`<img src="${escapeHtml(item.image_url)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:'<span>无图</span>'}</div><div><a href="${escapeHtml(item.product_url)}" target="_blank" rel="noopener noreferrer"><b>${escapeHtml(item.title)}</b></a><small>${escapeHtml(item.ozon_product_id||item.candidate_id)} · ${escapeHtml(item.category||'类目未知')}</small></div></div></td><td><span class="research-score" title="销量、增长、竞争、评分和评论的可验证指标加权">${escapeHtml(item.opportunity_score??'—')}</span><small>机会评分</small></td><td>${escapeHtml(metrics)}${item.growth_percent?`<small class="research-growth">增长 ${escapeHtml(item.growth_percent)}%</small>`:''}</td><td>${escapeHtml(competition)}<small>${escapeHtml(conversion||item.seller||'更多指标未公开')}</small></td><td><small>${escapeHtml((item.match_reasons||[]).join('；'))}</small></td><td><span class="research-status ${String(item.decision||'NEW').toLowerCase()}">${escapeHtml(researchDecisionName(item.decision))}</span>${item.pipeline_id?`<small>任务 ${escapeHtml(item.pipeline_id)}</small>`:''}</td><td>${escapeHtml(formatDate(item.updated_at))}</td><td><div class="catalog-row-actions"><button type="button" data-research-shortlist="${escapeHtml(item.candidate_id)}">${item.decision==='SHORTLISTED'?'取消收藏':'收藏'}</button><button type="button" data-research-source="${escapeHtml(item.candidate_id)}">${item.pipeline_id?'打开任务':'找 1688 货源'}</button><button type="button" data-research-reject="${escapeHtml(item.candidate_id)}">淘汰</button></div></td></tr>`}).join(''):'<tr><td colspan="9" class="table-empty">候选池为空。先保存规则，再使用 Ozon 选品插件同步商品。</td></tr>';document.querySelectorAll('[data-research-shortlist]').forEach(button=>button.onclick=()=>updateResearchCandidate(button.dataset.researchShortlist,{decision:(state.marketResearch.candidates.find(item=>item.candidate_id===button.dataset.researchShortlist)?.decision==='SHORTLISTED'?'NEW':'SHORTLISTED')}));document.querySelectorAll('[data-research-reject]').forEach(button=>button.onclick=()=>updateResearchCandidate(button.dataset.researchReject,{decision:'REJECTED'}));document.querySelectorAll('[data-research-source]').forEach(button=>button.onclick=()=>openResearchSource(button.dataset.researchSource))}
const baseRenderResearchSelection=renderResearch;
renderResearch=function(){baseRenderResearchSelection();const rows=filteredResearch();document.querySelectorAll('#researchTable tr').forEach((tr,index)=>{const item=rows[index];if(!item)return;tr.insertAdjacentHTML('afterbegin',`<td><input type="checkbox" data-research-select="${escapeHtml(item.candidate_id)}" ${state.selectedResearchIds.has(String(item.candidate_id))?'checked':''} aria-label="选择 ${escapeHtml(item.title)}"></td>`);const actions=tr.querySelector('.catalog-row-actions');if(actions)actions.insertAdjacentHTML('beforeend',`<button type="button" class="row-delete" data-delete-research="${escapeHtml(item.candidate_id)}">删除</button>`) });document.querySelectorAll('[data-research-select]').forEach(control=>control.onchange=()=>{const id=String(control.dataset.researchSelect);control.checked?state.selectedResearchIds.add(id):state.selectedResearchIds.delete(id);updateResearchSelection(rows)});document.querySelectorAll('[data-delete-research]').forEach(button=>button.onclick=()=>deleteResearchCandidates([button.dataset.deleteResearch]));updateResearchSelection(rows)};
const baseRenderResearchDetails=renderResearch;
renderResearch=function(){baseRenderResearchDetails();document.querySelectorAll('#researchTable .catalog-row-actions').forEach((actions,index)=>{const item=filteredResearch()[index];if(item)actions.insertAdjacentHTML('afterbegin',`<button type="button" data-research-detail="${escapeHtml(item.candidate_id)}">趋势 / 利润</button>`)});document.querySelectorAll('[data-research-detail]').forEach(button=>button.onclick=()=>openResearchDetail(button.dataset.researchDetail));const profile=(state.marketResearch.profiles||[]).find(item=>item.profile_id===$('#researchProfile')?.value);if(profile&&profile.profile_id!==state.marketResearch.active_profile_id)setResearchRules(profile)};
const baseRenderResearchReview=renderResearch;
renderResearch=function(){baseRenderResearchReview();const rows=filteredResearch(),riskNames={LOW:'低风险',MEDIUM:'需复核',HIGH:'高风险'};document.querySelectorAll('#researchTable tr').forEach((tr,index)=>{const item=rows[index];if(!item)return;const scoreCell=tr.children[2];if(scoreCell)scoreCell.insertAdjacentHTML('beforeend',`<span class="research-risk ${String(item.risk_level||'LOW').toLowerCase()}" title="${escapeHtml((item.risk_flags||[]).map(flag=>flag.message).join('；')||'未发现可观察风险')}">${escapeHtml(riskNames[item.risk_level]||'待检查')}</span>`);const actions=tr.querySelector('.catalog-row-actions');if(actions&&item.decision!=='APPROVED')actions.insertAdjacentHTML('afterbegin',`<button type="button" class="research-approve" data-research-approve="${escapeHtml(item.candidate_id)}">审核通过</button>`)});document.querySelectorAll('[data-research-approve]').forEach(button=>button.onclick=()=>{const item=(state.marketResearch.candidates||[]).find(row=>String(row.candidate_id)===String(button.dataset.researchApprove));if(item?.risk_level==='HIGH'&&!confirm(`该商品存在高风险：\n${(item.risk_flags||[]).map(flag=>`• ${flag.message}`).join('\n')}\n\n仍要审核通过吗？`))return;updateResearchCandidate(button.dataset.researchApprove,{decision:'APPROVED'})});const profileId=$('#researchProfile')?.value||state.marketResearch.active_profile_id||'default',pool=(state.marketResearch.candidates||[]).filter(item=>String(item.profile_id||'default')===profileId),count=decision=>pool.filter(item=>item.decision===decision).length;$('#researchMetrics').innerHTML=[['当前方案候选',pool.length,'与其他方案完全隔离'],['待审核',count('NEW'),'等待运营判断'],['已收藏 / 通过',`${count('SHORTLISTED')} / ${count('APPROVED')}`,'通过后进入货源匹配'],['已找到货源',count('SOURCED'),'已创建上架任务']].map(([label,value,hint])=>`<article><span>${label}</span><strong>${escapeHtml(value)}</strong><small>${hint}</small></article>`).join('')};
function updateResearchSelection(rows=filteredResearch()){const selected=state.selectedResearchIds.size;$('#deleteSelectedResearchBtn').textContent=`删除（${selected}）`;$('#deleteSelectedResearchBtn').disabled=!selected||!hasPermission('stage.run');const all=rows.length>0&&rows.every(item=>state.selectedResearchIds.has(String(item.candidate_id)));$('#researchSelectAll').checked=all;$('#researchSelectAll').indeterminate=!all&&rows.some(item=>state.selectedResearchIds.has(String(item.candidate_id)))}
async function deleteResearchCandidates(ids){const unique=[...new Set(ids.map(String))];if(!unique.length)return;if(!confirm(`确认删除选中的 ${unique.length} 条 Ozon 候选商品资料？已绑定的 ERP 商品任务不会随之删除。`))return;try{const result=await api('/api/research/candidates/batch-delete',{method:'POST',body:JSON.stringify({candidate_ids:unique,confirm_delete:true})});state.marketResearch=result.research;const removed=new Set(result.deleted||[]);state.selectedResearchIds=new Set([...state.selectedResearchIds].filter(id=>!removed.has(id)));renderResearch();toast(`已删除 ${removed.size} 条候选商品`)}catch(error){toast(error.message,true)}}
async function loadResearch(){try{state.marketResearch=await api('/api/research');const profiles=state.marketResearch.profiles||[];$('#researchProfile').innerHTML=profiles.length?profiles.map(item=>`<option value="${escapeHtml(item.profile_id)}">${escapeHtml(item.profile_name)}</option>`).join(''):'<option value="default">默认方案</option>';$('#researchProfile').value=state.marketResearch.active_profile_id||'default';setResearchRules(state.marketResearch.rules);renderResearch()}catch(error){toast(error.message,true)}}
async function saveResearchRules(event){event.preventDefault();try{const profile=$('#researchProfile');const payload={...researchRulesPayload(),profile_id:profile.value,profile_name:profile.selectedOptions[0]?.textContent||'默认方案'};const result=await api('/api/research/rules',{method:'POST',body:JSON.stringify(payload)});state.marketResearch.rules=result.rules;await loadResearch();toast(`选品方案“${result.rules.profile_name}”已保存并启用`)}catch(error){toast(error.message,true)}}
function newResearchProfile(){const name=prompt('请输入新选品方案名称');if(!name?.trim())return;const id=`plan-${Date.now()}`;$('#researchProfile').insertAdjacentHTML('beforeend',`<option value="${id}">${escapeHtml(name.trim().slice(0,80))}</option>`);$('#researchProfile').value=id;$('#researchRulesState').textContent='新方案尚未保存'}
async function copyResearchProfile(){const source=$('#researchProfile').selectedOptions[0]?.textContent||'选品方案';const name=prompt('请输入复制后的方案名称',`${source} - 副本`);if(!name?.trim())return;try{const payload={...researchRulesPayload(),profile_id:`plan-${Date.now()}`,profile_name:name.trim().slice(0,80)};await api('/api/research/rules',{method:'POST',body:JSON.stringify(payload)});await loadResearch();toast(`已复制并启用“${payload.profile_name}”`)}catch(error){toast(error.message,true)}}
async function deleteResearchProfile(){const profile=$('#researchProfile'),id=profile.value,name=profile.selectedOptions[0]?.textContent||id;const count=(state.marketResearch.candidates||[]).filter(item=>String(item.profile_id||'default')===id).length;if((state.marketResearch.profiles||[]).length<=1){toast('至少需要保留一个选品方案',true);return}if(!confirm(`确认删除选品方案“${name}”${count?`及其 ${count} 个候选商品`:''}？已创建的 ERP 商品任务不会删除。`))return;try{const result=await api(`/api/research/profiles/${encodeURIComponent(id)}`,{method:'DELETE',body:JSON.stringify({delete_candidates:true})});state.marketResearch=result.research;state.selectedResearchIds.clear();await loadResearch();toast(`已删除方案“${name}”`)}catch(error){toast(error.message,true)}}
function researchSparkline(rows,key,color){const values=rows.map(row=>Number(row[key])).filter(Number.isFinite);if(!values.length)return'<div class="research-chart-empty">暂无数据</div>';const min=Math.min(...values),max=Math.max(...values),span=max-min||1;const points=values.map((value,index)=>`${values.length===1?50:(index/(values.length-1))*100},${38-((value-min)/span)*32}`).join(' ');return`<svg viewBox="0 0 100 44" preserveAspectRatio="none" role="img"><polyline points="${points}" fill="none" stroke="${color}" stroke-width="2" vector-effect="non-scaling-stroke"/><circle cx="${values.length===1?50:100}" cy="${38-((values.at(-1)-min)/span)*32}" r="2.2" fill="${color}"/></svg><small>${escapeHtml(values.at(-1))}</small>`}
function openResearchDetail(id){const item=(state.marketResearch.candidates||[]).find(row=>String(row.candidate_id)===String(id));if(!item)return;$('#researchDetailTitle').textContent=item.title||'候选商品趋势';const econ=item.economics||{},calc=econ.calculation||{},riskNames={LOW:'低风险',MEDIUM:'需复核',HIGH:'高风险'};$('#researchDetailSummary').innerHTML=[['机会分',item.opportunity_score||'—','可验证指标加权'],['风险等级',riskNames[item.risk_level]||'待检查',(item.risk_flags||[]).map(flag=>flag.message).join('；')||'未发现可观察风险'],['单件利润',econ.status==='READY'?`¥${calc.unit_profit_cny}`:'待补充',econ.reason||`${calc.sales_margin_percent||'—'}% 毛利率`],['保本售价',econ.status==='READY'?`¥${calc.break_even_price_cny}`:'—',econ.status==='READY'?`建议 ¥${calc.suggested_price_cny}`:'绑定真实货源后计算']].map(([label,value,hint])=>`<article><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong><small>${escapeHtml(hint)}</small></article>`).join('');const history=(item.metric_history||[]).slice(),rows=history.slice().reverse();const charts=history.length?`<div class="research-trend-grid">${[['price_rub','售价 ₽','#087565'],['orders','订购量','#b77a16'],['opportunity_score','机会分','#c74232']].map(([key,label,color])=>`<article><b>${label}</b>${researchSparkline(history,key,color)}</article>`).join('')}</div>`:'';$('#researchTrendTable').innerHTML=rows.length?`${charts}<table><thead><tr><th>采集时间</th><th>售价 ₽</th><th>销量</th><th>销售额 ₽</th><th>卖家</th><th>增长率</th><th>机会分</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${escapeHtml(formatDate(row.captured_at))}</td><td>${escapeHtml(row.price_rub??'—')}</td><td>${escapeHtml(row.orders??'—')}</td><td>${escapeHtml(row.revenue_rub??'—')}</td><td>${escapeHtml(row.sellers??'—')}</td><td>${escapeHtml(row.growth_percent??'—')}%</td><td>${escapeHtml(row.opportunity_score??'—')}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">再次同步该商品后将形成历史趋势。</div>';$('#researchDetailDialog').showModal()}
async function updateResearchCandidate(id,payload){try{await api(`/api/research/candidates/${encodeURIComponent(id)}`,{method:'POST',body:JSON.stringify(payload)});await loadResearch();toast('候选品状态已更新')}catch(error){toast(error.message,true)}}
function openResearchSource(id){const item=(state.marketResearch.candidates||[]).find(row=>row.candidate_id===id);if(!item)return;if(item.pipeline_id){selectPipeline(item.pipeline_id).then(()=>showWorkspace('products'));return}state.researchCandidateId=id;$('#researchSourceTitle').textContent=`绑定货源 · ${item.title}`;$('#researchSourcePreview').innerHTML=`${item.image_url?`<img src="${escapeHtml(item.image_url)}" alt="">`:''}<div><b>${escapeHtml(item.title)}</b><small>${escapeHtml(item.product_url)}</small></div>`;$('#researchSourceStore').innerHTML=storeOptions();$('#researchSourceOffer').value='';$('#researchSourceConfirm').checked=false;$('#researchSourceDialog').showModal()}
async function sourceResearchCandidate(event){event.preventDefault();if(!$('#researchSourceConfirm').checked){toast('请确认允许调用 AlphaShop API',true);return}try{const result=await api(`/api/research/candidates/${encodeURIComponent(state.researchCandidateId)}/source`,{method:'POST',body:JSON.stringify({offer_id:$('#researchSourceOffer').value.trim(),store_id:$('#researchSourceStore').value,confirm_external_request:true})});$('#researchSourceDialog').close();await load();await loadResearch();await selectPipeline(result.pipeline.pipeline_id);showWorkspace('products');const economics=result.candidate?.economics||{};toast(economics.status==='READY'?`货源已采集 · 单件利润 ¥${economics.calculation.unit_profit_cny} · 毛利率 ${economics.calculation.sales_margin_percent}%`:`货源已采集；利润待补充：${economics.reason||'缺少真实参数'}`,economics.status!=='READY')}catch(error){toast(error.message,true)}}
